import * as THREE from 'three';
function getGeometryFromShape(shape) {
    let geometry;
    switch (shape) {
        case 'cube':
            geometry = new THREE.BoxGeometry(1, 1, 1, 1, 1, 1);
            break;
        case 'sphere':
            geometry = new THREE.SphereGeometry(1, 16, 16);
            break;
        case 'plane':
            geometry = new THREE.PlaneGeometry(1, 1, 1, 1);
            break;
        case 'point':
            geometry = new THREE.SphereGeometry(0.04, 32, 32);
            break;
    }
    return geometry;
}
/**
 * A helper class for previewing trigger shapes.
 */
export class TriggerPreviewMesh extends THREE.Mesh {
    /**
     * Constructs a trigger preview mesh.
     * @param shape - The shape of the trigger.
     * @param isTrigger - Whether or not the trigger is a trigger or a collider.
     */
    constructor(shape, isTrigger) {
        const material = new THREE.MeshBasicMaterial({ wireframe: true });
        super(getGeometryFromShape(shape), material);
        this.shape = shape;
        this.setIsTrigger(isTrigger);
    }
    /**
     * Sets whether or not the trigger is a trigger or a collider.
     * @param isTrigger - Whether or not the trigger is a trigger or a collider.
     */
    setIsTrigger(isTrigger) {
        const color = isTrigger ? 'orange' : 'purple';
        this.material.color.set(color);
    }
}
