import { useIsLoaded } from '@zcomponent/core';
import { ZHTMLElement } from '@zcomponent/html/lib/HTMLElement';
import { default as ModelPreview } from './ModelPreview.zcomp';
/**
 * @zcomponent
 */
export class AnimationList extends ZHTMLElement {
    constructor(contextManager, props) {
        super(contextManager, props, document.createElement('ul'));
        this._loaded = () => {
            const zcomp = this.getZComponentInstance(ModelPreview);
            const gltf = zcomp.nodes.GLTF;
            this.register(gltf.animationClips, this._updateClips);
        };
        this._updateClips = (clips) => {
            const zcomp = this.getZComponentInstance(ModelPreview);
            const gltf = zcomp.nodes.GLTF;
            this.element.innerHTML = '';
            for (const [name, clip] of clips.entries()) {
                const label = document.createElement('li');
                label.innerText = name;
                this.element.appendChild(label);
                const button = document.createElement('button');
                button.classList.add('inline');
                button.innerText = '▶';
                button.addEventListener('click', () => {
                    gltf.mixer.value?.stopAllAction();
                    gltf.mixer.value?.clipAction(clip).play();
                });
                label.appendChild(button);
            }
        };
        const test = document.createElement('li');
        test.innerText = 'Test';
        this.element.appendChild(test);
        this.register(useIsLoaded(contextManager), this._loaded);
    }
}
