import * as Data from './data';
import { PropertyTrack } from './animation/tracks/propertytrack';
import { Clip } from './animation/clips/clip';
import { LayerClip } from './animation/layerclip';
import { Layer } from './animation/layer';
import { ClipTrack } from './animation/tracks/cliptrack';
import { Bezier } from './animation/bezier';
import { StreamTrack } from './animation/tracks/streamtrack';
import { FunctionTrack } from './animation/tracks/functiontrack';
/**
 * Creates a track from the provided data.
 *
 * This function processes the given track data and creates an appropriate track instance based on the track type.
 * @param zcomp - The ZComponent instance.
 * @param anim - The Animation instance to which the track will belong.
 * @param data - The data object defining the track.
 * @returns A Track instance if successful, or undefined if the track cannot be created.
 */
export function createTrackFromData(zcomp, anim, data) {
    switch (data.type) {
        case Data.TrackType.Property: {
            const entity = zcomp.entityByID.get(data.entityID);
            if (!entity)
                return;
            const ret = new PropertyTrack(anim, data.entityID, entity, data.property, data.id);
            ret.setKeyframesById(processKeyframes(data.keyframes, anim.curves));
            ret.setWeightsById(processKeyframes(data.weight, anim.curves));
            ret.fadeParameters = resolvedFadeParameters(data.fadeParameters, anim.curves);
            ret.blend = data.blend ?? 'overlay';
            return ret;
        }
        case Data.TrackType.Clip: {
            const clip = zcomp.animation.clipByID.get(data.entityID);
            if (!clip)
                return;
            const ret = new ClipTrack(clip, data.id);
            ret.setBlocksById(data.data);
            ret.setWeightsById(processKeyframes(data.weight, anim.curves));
            return ret;
        }
        case Data.TrackType.Stream: {
            const entity = zcomp.entityByID.get(data.entityID);
            if (!entity)
                return;
            const ret = new StreamTrack(anim, entity, data.property);
            ret.setBlocksById(data.data);
            ret.setWeightsById(processKeyframes(data.weight, anim.curves));
            return ret;
        }
        case Data.TrackType.Function: {
            const ret = new FunctionTrack(anim);
            const blocks = Object.create(null);
            const dt = false; //isDesignTime(zcomp.contextManager);
            for (const block of Object.values(data.data)) {
                if (dt && !block?.runAtDesignTime)
                    continue;
                if (block?.type !== 'entity')
                    continue;
                const obj = zcomp.entityByID.get(block.entityID);
                const func = obj?.[block.functionName];
                if (typeof func !== 'function')
                    continue;
                blocks[block.id] = {
                    ...block,
                    obj,
                    func,
                };
            }
            ret.setBlocksById(blocks);
            return ret;
        }
    }
    return undefined;
}
/**
 * Processes keyframe data to handle easing via bezier curves.
 *
 * This function iterates over the provided keyframes and applies bezier curve transformations to keyframes with defined easing properties.
 * @param keyframes - The object containing keyframe data.
 * @param beziers - The object containing bezier curve definitions.
 * @returns A transformed set of keyframes with bezier curves applied.
 */
export function processKeyframes(keyframes, beziers) {
    let needsNew = false;
    const keyframeArray = Object.values(keyframes);
    for (const keyframe of keyframeArray) {
        if (keyframe?.easing) {
            const bezier = beziers[keyframe.easing];
            if (bezier) {
                needsNew = true;
                break;
            }
        }
    }
    if (!needsNew)
        return keyframes;
    const ret = Object.create(null);
    for (const keyframe of keyframeArray) {
        if (!keyframe)
            continue;
        if (!keyframe.easing) {
            ret[keyframe.id] = keyframe;
            continue;
        }
        const bezier = beziers[keyframe.easing];
        if (!bezier) {
            ret[keyframe.id] = keyframe;
            continue;
        }
        ret[keyframe.id] = {
            ...keyframe,
            easing: bezier,
        };
    }
    return ret;
}
/**
 * Creates a Clip instance from provided data.
 *
 * This function constructs a new Clip instance using the given data, determining its length either from the data or by calculating it from track keyframes.
 * @param zcomp - The ZComponent instance.
 * @param anim - The Animation instance to which the clip will belong.
 * @param data - The data object defining the clip.
 * @returns A new Clip instance.
 */
export function createClipFromData(zcomp, anim, data) {
    let length = data.length;
    if (length === undefined) {
        length = 0;
        for (const track of Object.values(data.tracks)) {
            if (!track)
                continue;
            switch (track.type) {
                case Data.TrackType.Property:
                    for (const keyframe of Object.values(track.keyframes)) {
                        if (!keyframe)
                            continue;
                        length = Math.max(length, keyframe.t);
                    }
                    break;
                case Data.TrackType.Clip:
                    for (const keyframe of Object.values(track.data)) {
                        if (!keyframe)
                            continue;
                        length = Math.max(length, keyframe.t0);
                        length = Math.max(length, keyframe.t1 ?? length);
                    }
                    break;
                case Data.TrackType.Stream:
                    for (const keyframe of Object.values(track.data)) {
                        if (!keyframe)
                            continue;
                        length = Math.max(length, keyframe.t0);
                        if (keyframe.t1)
                            length = Math.max(length, keyframe.t1);
                    }
                    break;
            }
        }
    }
    const ret = new Clip(anim, length, data.scriptName, data.id);
    ret.defaultFadeParameters = resolvedFadeParameters(data.defaultFadeParameters, anim.curves);
    zcomp.animation.clipByID.set(data.id, ret);
    return ret;
}
/**
 * Resolves fade parameters with bezier curves.
 *
 * This function checks if the provided fade parameters include easing and, if so, applies the corresponding bezier curve.
 * @param fade - The fade parameters, potentially including easing.
 * @param beziers - The object containing bezier curve definitions.
 * @returns The resolved fade parameters.
 */
function resolvedFadeParameters(fade, beziers) {
    if (!fade?.easing)
        return fade;
    const bezier = beziers[fade?.easing];
    if (!bezier)
        return fade;
    return {
        ...fade,
        easing: bezier,
    };
}
/**
 * Updates a Clip instance with data from a Data.Clip object.
 *
 * This function modifies an existing Clip instance, updating its properties and tracks based on the provided data.
 * @param zcomp - The ZComponent instance.
 * @param clip - The Clip instance to update.
 * @param data - The data object defining the updates for the clip.
 */
export function updateClipFromData(zcomp, clip, data) {
    clip.defaultFadeParameters = resolvedFadeParameters(data.defaultFadeParameters, zcomp.animation.curves);
    clip.length = data.length;
    clip.clearTracks();
    const tracks = Object.values(data.tracks);
    tracks.sort((atrack, btrack) => {
        let a = atrack.order ?? 'A0';
        let b = btrack.order ?? 'A0';
        if (a === b) {
            a = atrack.id;
            b = btrack.id;
        }
        return a < b ? -1 : 1;
    });
    for (const track of Object.values(tracks)) {
        if (!track)
            continue;
        const instance = createTrackFromData(zcomp, clip.animation, track);
        if (instance)
            clip.addTrack(instance);
    }
}
/**
 * Creates a LayerClip from provided data.
 *
 * This function constructs a new LayerClip instance using the given data, setting properties like playback speed, looping, and play-at-start.
 * @param zcomp - The ZComponent instance.
 * @param layer - The Layer instance to which the LayerClip will belong.
 * @param data - The data object defining the LayerClip.
 * @returns A new LayerClip instance if successful, or undefined if the clip cannot be created.
 */
export function createLayerClipFromData(zcomp, layer, data) {
    const clip = zcomp.animation.clipByID.get(data.clipId);
    if (!clip)
        return;
    const ret = new LayerClip(layer, clip, data.scriptName, data.id);
    ret.defaultPlaySpeed = data.playbackSpeed ?? 1;
    if (data.reverse)
        ret.defaultPlaySpeed *= -1;
    ret.defaultLoop = data.loop ?? false;
    ret.playAtStart = data.playAtStart ?? false;
    return ret;
}
/**
 * Creates a Layer from provided data.
 *
 * This function constructs a new Layer instance using the given data, setting properties like active state and default fade parameters.
 * @param zcomp - The ZComponent instance.
 * @param anim - The Animation instance to which the layer will belong.
 * @param data - The data object defining the Layer.
 * @returns A new Layer instance if successful, or undefined if the layer cannot be created.
 */
export function createLayerFromData(zcomp, anim, data) {
    const ret = new Layer(anim, data.scriptName, data.id);
    ret.active = undefined;
    ret.defaultFadeParameters = resolvedFadeParameters(data.defaultFadeParameters, anim.curves);
    if (data.defaultClip === null)
        ret.active = null;
    for (const layerClip of Object.values(data.clips)) {
        if (!layerClip)
            continue;
        const instance = createLayerClipFromData(zcomp, ret, layerClip);
        if (!instance)
            continue;
        if (data.defaultClip === layerClip.id)
            ret.active = instance;
    }
    return ret;
}
/**
 * Populates an Animation instance with tracks from provided data.
 *
 * This function iterates over the provided animation data, creating and adding tracks to the animation's clips.
 * @param zcomp - The ZComponent instance.
 * @param anim - The Animation instance to populate.
 * @param data - The data object containing information about the animation.
 */
export function populateAnimationTracksFromData(zcomp, anim, data) {
    const clips = resolveClipDependencies(data.clips).reverse();
    for (const clipData of Object.values(clips)) {
        const clip = anim.clipByID.get(clipData.id);
        if (!clip)
            continue;
        const tracks = Object.values(clipData.tracks);
        tracks.sort((atrack, btrack) => {
            let a = atrack.order ?? 'A0';
            let b = btrack.order ?? 'A0';
            if (a === b) {
                a = atrack.id;
                b = btrack.id;
            }
            return a < b ? -1 : 1;
        });
        for (const track of Object.values(tracks)) {
            if (!track)
                continue;
            const instance = createTrackFromData(zcomp, anim, track);
            if (instance)
                clip.addTrack(instance);
        }
    }
}
/**
 * Constructs the structure of an Animation instance from provided data.
 *
 * This function builds the structure of an animation, including creating clips, layers, and setting up bezier curves.
 * @param zcomp - The ZComponent instance.
 * @param anim - The Animation instance to construct.
 * @param data - The data object containing information about the animation.
 */
export function populateAnimationStructureFromData(zcomp, anim, data) {
    const clips = resolveClipDependencies(data.clips).reverse();
    for (const clip of Object.values(clips)) {
        if (!clip)
            continue;
        createClipFromData(zcomp, anim, clip);
    }
    const layers = Object.values(data.layers);
    layers.sort((alayer, blayer) => {
        let a = alayer.order ?? 'A0';
        let b = blayer.order ?? 'A0';
        if (a === b) {
            a = alayer.id;
            b = blayer.id;
        }
        return a < b ? -1 : 1;
    });
    for (const curve of Object.values(data.curves)) {
        if (!curve)
            continue;
        anim.curves[curve.id] = new Bezier(curve.curve);
    }
    for (const layer of Object.values(layers)) {
        if (!layer)
            continue;
        const instance = createLayerFromData(zcomp, anim, layer);
        if (!instance)
            continue;
        anim.addLayer(instance);
    }
}
/** Depth-first topological sort of clips  */
function resolveClipDependencies(clips) {
    const ret = [];
    const nodesWithoutPermanentMark = new Set(Object.values(clips));
    const nodesWithTemporaryMark = new Set();
    function visit(n) {
        if (!nodesWithoutPermanentMark.has(n))
            return true; // n has permanent mark
        if (nodesWithTemporaryMark.has(n))
            return false; // cycle
        nodesWithTemporaryMark.add(n);
        for (const track of Object.values(n.tracks)) {
            if (track?.type !== Data.TrackType.Clip)
                continue;
            const clip = clips[track.entityID];
            if (!clip)
                continue;
            if (!visit(clip))
                return false;
        }
        nodesWithTemporaryMark.delete(n);
        nodesWithoutPermanentMark.delete(n);
        ret.splice(0, 0, n);
        return true;
    }
    let iteration = 100000;
    while (iteration > 0) {
        const nextVal = nodesWithoutPermanentMark.values().next().value;
        if (!nextVal)
            break;
        iteration--;
        if (!visit(nextVal))
            break;
    }
    return ret;
}
