import { Observable, useCanvasSize } from '@zcomponent/core';
import * as THREE from 'three';
import { Camera } from './Camera';
/**
 *
 * Camera that uses perspective projection.
 *
 * This projection mode is designed to mimic the way the human eye sees.
 * It is the most common projection mode used for rendering a 3D scene.
 *
 * Root element: [THREE.PerspectiveCamera](https://threejs.org/docs/index.html#api/en/cameras/PerspectiveCamera)
 *
 *
 * @zcomponent
 * @zgroup Cameras
 * @zicon camera
 * @ztag three/Object3D/Camera/PerspectiveCamera
 * @ztag three/Object3D/Group/Camera
 * @zparents three/Object3D/Group/**
 */
export class PerspectiveCamera extends Camera {
    constructor(mgr, props) {
        super(mgr, props, new THREE.PerspectiveCamera());
        /** @zprop
         * @zgroup PerspectiveCamera
         * @zgrouppriority 20
         * @zdefault 50
         */
        this.fov = new Observable(50, v => {
            this.element.fov = v;
            this.element.updateProjectionMatrix();
            this._helper?.update();
        });
        /** @zprop
         * @zgroup PerspectiveCamera
         * @zgrouppriority 20
         * @zdefault 2000
         */
        this.far = new Observable(2000, v => {
            this.element.far = v;
            this.element.updateProjectionMatrix();
            this._helper?.update();
        });
        /** @zprop
         * @zgroup PerspectiveCamera
         * @zgrouppriority 20
         * @zdefault 0.1
         */
        this.near = new Observable(0.1, v => {
            this.element.near = v;
            this.element.updateProjectionMatrix();
            this._helper?.update();
        });
        /** @zprop
         * @zgroup PerspectiveCamera
         * @zgrouppriority 20
         * @zdefault 1
         */
        this.zoom = new Observable(1, v => {
            this.element.zoom = v;
            this.element.updateProjectionMatrix();
            this._helper?.update();
        });
        /** @zprop
         * @zgroup PerspectiveCamera
         * @zgrouppriority 20
         * @zdefault 0
         */
        this.filmOffset = new Observable(0, v => {
            this.element.filmOffset = v;
            this.element.updateProjectionMatrix();
            this._helper?.update();
        });
        /** @zprop
         * @zgroup PerspectiveCamera
         * @zgrouppriority 20
         * @zdefault 35
         */
        this.filmGauge = new Observable(35, v => {
            this.element.filmGauge = v;
            this.element.updateProjectionMatrix();
            this._helper?.update();
        });
        this.register(useCanvasSize(this.contextManager), size => {
            this.element.aspect = size[0] / size[1];
            this.element.updateProjectionMatrix();
        });
        if (props.activateAtStart ?? true)
            this.activate();
    }
}
