import * as THREE from 'three';
import { translateEncoding } from './context';
// The naming convention of uv buffer attributes has been changed.
// before 152 | 152 and after
// uv - uv
// uv2 - uv1
export function legacy_get_intersection_UV2(intersection) {
    const uv2 = Number(THREE.REVISION) < 152 ? 'uv2' : 'uv1';
    return intersection[uv2];
}
// Texture.encoding has been replaced with Texture.colorSpace with THREE.NoColorSpace as the default value.
export function legacy_set_texture_encoding(texture, v) {
    if ('colorSpace' in texture)
        texture.colorSpace = translateEncoding(v);
    else if ('encoding' in texture)
        texture.encoding = translateEncoding(v);
}
