import { Observable, useCanvasSize } from '@zcomponent/core';
import * as THREE from 'three';
import { Camera } from './Camera';
/**
 *
 * An orthographic camera component.
 *
 * In this projection mode, an object's size in the rendered image stays constant regardless of its distance from the camera.
 * This can be useful for rendering 2D scenes and UI elements, amongst other things.
 *
 * Root element: [THREE.OrthographicCamera](https://threejs.org/docs/index.html#api/en/cameras/OrthographicCamera)
 *
 * @zcomponent
 * @zgroup Cameras
 * @zicon camera
 * @ztag three/Object3D/Camera/OrthographicCamera
 * @zparents three/Object3D/Group/**
 */
export class OrthographicCamera extends Camera {
    /**
     * Constructs a new OrthographicCamera.
     * @param contextManager - The context manager.
     * @param props - The properties required to construct the OrthographicCamera.
     */
    constructor(contextManager, props) {
        super(contextManager, props, new THREE.OrthographicCamera());
        /**
         * Camera frustum far plane.
         * @zprop
         * @zgroup PerspectiveCamera
         * @zgrouppriority 20
         * @zdefault 2000
         */
        this.far = new Observable(2000, v => {
            this.element.far = v;
            this.element.updateProjectionMatrix();
            this._helper?.update();
        });
        /**
         * Camera frustum near plane.
         * @zprop
         * @zgroup PerspectiveCamera
         * @zgrouppriority 20
         * @zdefault 0.1
         */
        this.near = new Observable(0.1, v => {
            this.element.near = v;
            this.element.updateProjectionMatrix();
            this._helper?.update();
        });
        /**
         * An observable for getting or setting the zoom factor of the camera.
         *
         * Default is 1.
         * @zprop
         * @zgroup PerspectiveCamera
         * @zgrouppriority 20
         * @zdefault 1
         */
        this.zoom = new Observable(1, v => {
            this.element.zoom = v;
            this.element.updateProjectionMatrix();
            this._helper?.update();
        });
        this.register(useCanvasSize(contextManager), size => {
            const aspect = size[0] / size[1];
            this.element.top = props.top ?? 5;
            this.element.bottom = props.bottom ?? -5;
            const height = this.element.top - this.element.bottom;
            this.element.left = props.left ?? -0.5 * aspect * height;
            this.element.right = props.right ?? 0.5 * aspect * height;
            this.element.updateProjectionMatrix();
        });
        if (props.activateAtStart)
            this.activate();
    }
}
