import * as THREE from 'three';
import { Trigger } from './Trigger';
import { TriggerShape } from './ITrigger';
/**
 * A sphere trigger component.
 * @zcomponent
 * @zgroup Trigger
 * @zicon shapes
 * @zparents three/Object3D/**
 */
export class SphereTrigger extends Trigger {
    /**
     * Constructs a sphere trigger.
     * @param ctx - The context manager.
     * @param props - The properties for trigger construction, including shape.
     */
    constructor(ctx, props) {
        super(ctx, { ...props, shape: TriggerShape.Sphere });
        /**
         * Represents the world-space bounding sphere of the trigger.
         */
        this.worldBoundingSphere = new THREE.Sphere();
        this.previewMesh.geometry.computeBoundingSphere();
    }
    /**
     * Updates the world-space bounding sphere based on the trigger's current state.
     */
    update() {
        this.worldBoundingSphere.copy(this.previewMesh.geometry.boundingSphere).applyMatrix4(this.previewMesh.matrixWorld);
    }
}
