import * as THREE from 'three';
import { Object3D } from './Object3D';
/**
 * Collect multiple nodes together.
 *
 * The child nodes' locations in 3D space are relative to the location of the group node.
 *
 * Root element: [THREE.Group](https://threejs.org/docs/index.html?q=Grou#api/en/objects/Group)
 *
 * @zcomponent
 * @zicon group
 * @ztag three/Object3D/Group/Group
 * @zparents three/Object3D/Group/**
 */
export class Group extends Object3D {
    constructor(ctx, props, parentForChildren) {
        super(ctx, props, new THREE.Group(), parentForChildren);
    }
}
