import { AudioContextContext, isDesignTime, nextUserEvent, Observable, registerLoadable, started } from '@zcomponent/core';
import * as THREE from 'three';
import { Texture } from './Texture';
import { EncodingType } from '../../context';
import { legacy_set_texture_encoding } from '../../utils';
/**
 *
 * Extends the Texture component to provide functionality for creating and managing video textures.
 *
 * This component enables the use of video files as textures in 3D scenes, supporting features like autoplay, audio layers, and legacy audio.
 *
 *
 * @zcomponent
 * @zgroup Texture
 * @zicon movie
 * @ztag three/Texture/VideoTexture
 * @zparents three/Material/**
 * @zstream
 */
export class VideoTexture extends Texture {
    /**
     * Creates an instance of VideoTexture.
     * @param mgr - The context manager.s
     * @param props VideoTextureConstructorProps to define the properties of the video texture.
     */
    constructor(mgr, props) {
        const element = document.createElement('video');
        element.crossOrigin = 'anonymous';
        element.playsInline = true;
        element.muted = true;
        registerLoadable(mgr, new Promise((resolve, reject) => {
            element.addEventListener('canplaythrough', () => resolve());
            element.addEventListener('error', () => reject());
        }));
        element.src = props.source;
        const texture = new THREE.VideoTexture(element);
        legacy_set_texture_encoding(texture, EncodingType.sRGBEncoding);
        super(mgr, props, texture);
        this._hadUserEvent = false;
        /**
         * Observable property to control the muted state of the video.
         * When set to true, the video plays without sound.
         * @zprop
         * @zdefault false
         * @zgroup VideoTexture
         * @zgrouppriority 20
         */
        this.muted = new Observable(false);
        this._updateMute = () => {
            if (!this.videoElement || !this._hadUserEvent)
                return;
            this.videoElement.muted = this.muted.value;
        };
        /**
         * The volume of the video.
         * @zprop
         * @ztype proportion
         * @zdefault 1
         */
        this.volume = new Observable(1, v => (this._gain.gain.value = v));
        /**
         * Whether the video should loop.
         * @zprop
         * @zdefault false
         * @zgroup VideoTexture
         * @zgrouppriority 20
         */
        this.loop = new Observable(false, v => {
            this.videoElement.loop = v;
        });
        this.videoElement = element;
        const audioContextContext = mgr.get(AudioContextContext);
        this._gain = new GainNode(audioContextContext.audioContext);
        if (props.legacyAudio !== true) {
            const audioSource = audioContextContext.audioContext.createMediaElementSource(element);
            audioSource.connect(this._gain);
            this._gain.connect(audioContextContext.getLayer(props.audioLayer));
        }
        this.register(this.muted, this._updateMute);
        nextUserEvent(mgr).then(() => {
            this._hadUserEvent = true;
            this._updateMute();
        });
        if (!isDesignTime(mgr) && props.autoplay)
            started(mgr).then(() => this.play());
        element.load();
    }
    /**
     * Disposes of the video texture.
     */
    dispose() {
        this.videoElement.pause();
        this.videoElement.src = '';
        return super.dispose();
    }
    /**
     * Plays the video.
     * @zprop
     **/
    play(opts) {
        this.videoElement.playbackRate = opts?.speed ?? 1;
        this.videoElement.play();
    }
    /**
     * Pauses the video.
     * @zprop
     * */
    pause() {
        this.videoElement.pause();
    }
    /**
     * Stops the video and resets the current time to 0.
     * @zprop
     *
     */
    stop() {
        this.videoElement.pause();
        this.videoElement.currentTime = 0;
    }
    /**
     * Seeks to the specified time in milliseconds.
     * @zprop
     */
    seek(t) {
        this.videoElement.currentTime = t / 1000;
    }
    /**
     * @returns The current time in milliseconds.
     */
    currentTime() {
        return this.videoElement.currentTime * 1000;
    }
    /**
     *
     * @returns The length of the video in milliseconds.
     */
    length() {
        return isNaN(this.videoElement.duration) ? undefined : this.videoElement.duration * 1000;
    }
    /**
     *
     * @returns Whether the video is currently playing.
     */
    stalled() {
        return this.videoElement.readyState <= 2;
    }
}
