/* eslint-disable @typescript-eslint/no-empty-interface */
import { getComponentsByTags, useOnBeforeRender, Event, Observable, isDesignTime } from '@zcomponent/core';
import { Group } from '../../Group';
import * as THREE from 'three';
import { TriggerPreviewMesh } from './util/TriggerPreviewMesh';
import { CollisionManagerContext } from './util/CollisionManagerContext';
import { TriggerShape } from './ITrigger';
/**
 * Abstract base class for Trigger objects, extending the Group class.
 * Manages collision events, updates, and visualization in a 3D environment.
 */
export class Trigger extends Group {
    /**
     * Constructs a Trigger instance.
     * @param ctx The context manager for the trigger.
     * @param props The properties for trigger construction, including shape.
     */
    constructor(ctx, props) {
        super(ctx, props);
        /**
         * Specifies whether this trigger is a trigger or a collider.
         * @zprop
         * @zgroup Trigger
         * @zgrouppriority 20
         * @zdefault false
         * @zparents three/Object3D/**
         */
        this.isTrigger = new Observable(false);
        /**
         * Event triggered when a collision with another trigger starts.
         * @zui
         **/
        this.onCollisionEnter = new Event();
        /**
         * Event triggered when a collision with another trigger ends.
         * @zui
         **/
        this.onCollisionLeave = new Event();
        /**
         * Event triggered when a collision with another trigger continues in a new frame.
         * @zui
         * */
        this.onCollisionMove = new Event();
        this.didMove = false;
        this.previousWorldMatrix = new THREE.Matrix4();
        this.isReady = false;
        this._updateEnabled = (enabled) => {
            if (enabled)
                return;
            this.collidingComponents.forEach(component => {
                // basically we want to trigger a leave event for all colliders we are currently colliding with,
                // but do not emit one ourselves as we are disabled.
                component.onCollisionLeave.emit({ thisTrigger: component, otherTrigger: this });
            });
            this.collidingComponents.clear();
            this.didMove = false;
        };
        this.collidingComponents = new Set();
        this._frame = () => {
            const components = getComponentsByTags(this.contextManager, this.tags.value ?? []);
            this.update();
            this.updateMovementState();
            if (!this.isReady) {
                this.isReady = true;
                return;
            }
            const relevantComponents = Array.from(components).filter((component) => {
                if (!(component instanceof Trigger))
                    return false;
                if (component.isTrigger.value === this.isTrigger.value)
                    return false;
                if (component === this)
                    return false;
                return true;
            });
            const currentCollisions = new Set();
            for (const component of relevantComponents) {
                if (this.contextManager.get(CollisionManagerContext).isColliding(this, component)) {
                    currentCollisions.add(component);
                    if (!this.collidingComponents.has(component)) {
                        this.onCollisionEnter.emit({ thisTrigger: this, otherTrigger: component });
                    }
                    else {
                        if (this.didMove || component.didMove) {
                            this.onCollisionMove.emit({ thisTrigger: this, otherTrigger: component });
                        }
                    }
                }
            }
            for (const component of this.collidingComponents) {
                if (!currentCollisions.has(component)) {
                    this.onCollisionLeave.emit({ thisTrigger: this, otherTrigger: component });
                }
            }
            this.collidingComponents = currentCollisions;
        };
        this.shape = props.shape ?? TriggerShape.Cube;
        this.previewMesh = new TriggerPreviewMesh(this.shape, this.isTrigger.value);
        this.element.add(this.previewMesh);
        this.register(this.isTrigger, v => this.previewMesh?.setIsTrigger(v), { bindWhenDisabled: true });
        this.previewMesh.visible = isDesignTime(this.contextManager);
        this.register(this.enabledResolved, this._updateEnabled, { bindWhenDisabled: true });
        this.register(useOnBeforeRender(this.contextManager), this._frame);
    }
    updateMovementState() {
        this.element.updateWorldMatrix(true, true);
        const worldMatrixChanged = !this.element.matrixWorld.equals(this.previousWorldMatrix);
        this.didMove = worldMatrixChanged;
        this.previousWorldMatrix.copy(this.element.matrixWorld);
    }
}
