import * as THREE from 'three';
export class SoftShadows {
    constructor(options = {}) {
        this.size = options.size ?? 25;
        this.samples = options.samples ?? 10;
        this.focus = options.focus ?? 0;
        this.originalShaderChunk = THREE.ShaderChunk.shadowmap_pars_fragment;
        this.apply();
    }
    reset(camera, scene, gl) {
        scene.traverse(object => {
            const retyped = object;
            if (retyped?.material instanceof Array) {
                for (const material of retyped.material) {
                    gl.properties.remove(material);
                    material.dispose?.();
                }
            }
            else {
                gl.properties.remove(retyped.material);
                retyped?.material?.dispose?.();
            }
        });
        if (gl.info.programs)
            gl.info.programs.length = 0;
        gl.compile(scene, camera);
    }
    apply() {
        const pcssCode = this.generatePCSSCode();
        THREE.ShaderChunk.shadowmap_pars_fragment = this.originalShaderChunk
            .replace('#ifdef USE_SHADOWMAP', '#ifdef USE_SHADOWMAP\n' + pcssCode)
            .replace('#if defined( SHADOWMAP_TYPE_PCF )', '\nreturn PCSS(shadowMap, shadowCoord);\n#if defined( SHADOWMAP_TYPE_PCF )');
    }
    generatePCSSCode() {
        return `
      #define PENUMBRA_FILTER_SIZE float(${this.size})
      #define RGB_NOISE_FUNCTION(uv) (randRGB(uv))
      vec3 randRGB(vec2 uv) {
        return vec3(
          fract(sin(dot(uv, vec2(12.75613, 38.12123))) * 13234.76575),
          fract(sin(dot(uv, vec2(19.45531, 58.46547))) * 43678.23431),
          fract(sin(dot(uv, vec2(23.67817, 78.23121))) * 93567.23423)
        );
      }

      vec3 lowPassRandRGB(vec2 uv) {
        vec3 result = vec3(0);
        result += RGB_NOISE_FUNCTION(uv + vec2(-1.0, -1.0));
        result += RGB_NOISE_FUNCTION(uv + vec2(-1.0,  0.0));
        result += RGB_NOISE_FUNCTION(uv + vec2(-1.0, +1.0));
        result += RGB_NOISE_FUNCTION(uv + vec2( 0.0, -1.0));
        result += RGB_NOISE_FUNCTION(uv + vec2( 0.0,  0.0));
        result += RGB_NOISE_FUNCTION(uv + vec2( 0.0, +1.0));
        result += RGB_NOISE_FUNCTION(uv + vec2(+1.0, -1.0));
        result += RGB_NOISE_FUNCTION(uv + vec2(+1.0,  0.0));
        result += RGB_NOISE_FUNCTION(uv + vec2(+1.0, +1.0));
        result *= 0.111111111;
        return result;
      }
      vec3 highPassRandRGB(vec2 uv) {
        return RGB_NOISE_FUNCTION(uv) - lowPassRandRGB(uv) + 0.5;
      }

      vec2 vogelDiskSample(int sampleIndex, int sampleCount, float angle) {
        const float goldenAngle = 2.399963f;
        float r = sqrt(float(sampleIndex) + 0.5f) / sqrt(float(sampleCount));
        float theta = float(sampleIndex) * goldenAngle + angle;
        float sine = sin(theta);
        float cosine = cos(theta);
        return vec2(cosine, sine) * r;
      }
      float penumbraSize( const in float zReceiver, const in float zBlocker ) {
        return (zReceiver - zBlocker) / zBlocker;
      }
      float findBlocker(sampler2D shadowMap, vec2 uv, float compare, float angle) {
        float texelSize = 1.0 / float(textureSize(shadowMap, 0).x);
        float blockerDepthSum = float(${this.focus});
        float blockers = 0.0;

        int j = 0;
        vec2 offset = vec2(0.);
        float depth = 0.;

        #pragma unroll_loop_start
        for(int i = 0; i < ${this.samples}; i ++) {
          offset = (vogelDiskSample(j, ${this.samples}, angle) * texelSize) * 2.0 * PENUMBRA_FILTER_SIZE;
          depth = unpackRGBAToDepth( texture2D( shadowMap, uv + offset));
          if (depth < compare) {
            blockerDepthSum += depth;
            blockers++;
          }
          j++;
        }
        #pragma unroll_loop_end

        if (blockers > 0.0) {
          return blockerDepthSum / blockers;
        }
        return -1.0;
      }

      float vogelFilter(sampler2D shadowMap, vec2 uv, float zReceiver, float filterRadius, float angle) {
        float texelSize = 1.0 / float(textureSize(shadowMap, 0).x);
        float shadow = 0.0f;
        int j = 0;
        vec2 vogelSample = vec2(0.0);
        vec2 offset = vec2(0.0);
        #pragma unroll_loop_start
        for (int i = 0; i < ${this.samples}; i++) {
          vogelSample = vogelDiskSample(j, ${this.samples}, angle) * texelSize;
          offset = vogelSample * (1.0 + filterRadius * float(${this.size}));
          shadow += step( zReceiver, unpackRGBAToDepth( texture2D( shadowMap, uv + offset ) ) );
          j++;
        }
        #pragma unroll_loop_end
        return shadow * 1.0 / ${this.samples}.0;
      }

      float PCSS (sampler2D shadowMap, vec4 coords) {
        vec2 uv = coords.xy;
        float zReceiver = coords.z;
        float angle = highPassRandRGB(gl_FragCoord.xy).r * PI2;
        float avgBlockerDepth = findBlocker(shadowMap, uv, zReceiver, angle);
        if (avgBlockerDepth == -1.0) {
          return 1.0;
        }
        float penumbraRatio = penumbraSize(zReceiver, avgBlockerDepth);
        return vogelFilter(shadowMap, uv, zReceiver, 1.25 * penumbraRatio, angle);
      }`;
    }
    dispose() {
        THREE.ShaderChunk.shadowmap_pars_fragment = this.originalShaderChunk;
    }
}
