import { Event } from '@zcomponent/core';
import * as THREE from 'three';
import { SelectionBox } from 'three/examples/jsm/interactive/SelectionBox';
import { SelectionHelper } from 'three/examples/jsm/interactive/SelectionHelper';
class SelectionHelperFixed extends SelectionHelper {
    constructor(renderer, id) {
        super(renderer, id);
        this.enabled = false;
        this.pointerId = null;
        this.onKeyDown = (event) => {
            if (event.key === 'Alt') {
                this.enabled = true;
            }
        };
        this.onKeyUp = (event) => {
            if (event.key === 'Alt') {
                this.enabled = false;
            }
        };
        document.addEventListener('keydown', this.onKeyDown);
        document.addEventListener('keyup', this.onKeyUp);
    }
    onSelectOver() {
        this.element.parentElement?.removeChild(this.element);
        if (this.pointerId === null)
            return;
        this.renderer.domElement?.releasePointerCapture(this.pointerId);
        this.pointerId = null;
    }
    onSelectStart(event) {
        if (event.buttons !== 1)
            return;
        if (!this.enabled)
            return;
        this.pointerId = event.pointerId;
        this.renderer.domElement?.setPointerCapture(this.pointerId);
        this.element.style.display = 'none';
        const parentRect = this.renderer.domElement.parentElement?.getBoundingClientRect();
        this.renderer.domElement.parentElement?.appendChild(this.element);
        const adjustedX = event.clientX - (parentRect?.left || 0);
        const adjustedY = event.clientY - (parentRect?.top || 0);
        this.element.style.left = adjustedX + 'px';
        this.element.style.top = adjustedY + 'px';
        this.element.style.width = '0px';
        this.element.style.height = '0px';
        this.startPoint.x = adjustedX;
        this.startPoint.y = adjustedY;
    }
    onSelectMove(event) {
        if (event.buttons !== 1)
            return;
        if (!this.enabled)
            return;
        this.element.style.display = 'block';
        const parentRect = this.renderer.domElement.parentElement?.getBoundingClientRect();
        const maxX = parentRect?.width || window.innerWidth;
        const maxY = parentRect?.height || window.innerHeight;
        const adjustedX = event.clientX - (parentRect?.left || 0);
        const adjustedY = event.clientY - (parentRect?.top || 0);
        this.pointBottomRight.x = Math.min(Math.max(this.startPoint.x, adjustedX), maxX);
        this.pointBottomRight.y = Math.min(Math.max(this.startPoint.y, adjustedY), maxY);
        this.pointTopLeft.x = Math.max(Math.min(this.startPoint.x, adjustedX), 0);
        this.pointTopLeft.y = Math.max(Math.min(this.startPoint.y, adjustedY), 0);
        this.element.style.left = this.pointTopLeft.x + 'px';
        this.element.style.top = this.pointTopLeft.y + 'px';
        this.element.style.width = Math.min(this.pointBottomRight.x - this.pointTopLeft.x, maxX - this.pointTopLeft.x) + 'px';
        this.element.style.height = Math.min(this.pointBottomRight.y - this.pointTopLeft.y, maxY - this.pointTopLeft.y) + 'px';
    }
    dispose() {
        document.removeEventListener('keydown', this.onKeyDown);
        document.removeEventListener('keyup', this.onKeyUp);
        super.dispose();
    }
}
/**
 * A helper class to select objects in a scene.
 * Dragging the mouse will draw a selection box, selecting all objects that are
 * intersected by it.
 */
export class SelectionBoxHelper {
    constructor() {
        this.onSelected = new Event();
        this.enabled = false;
        this.lastSelection = [];
        this.normalizedDeviceCoordinates = new THREE.Vector2();
        this.onPointerDown = (event) => {
            if (!this.enabled)
                return;
            if (event.button !== 0)
                return;
            const normalizedCoordinates = this.updateNormalizedDeviceCoordinates(event);
            if (!normalizedCoordinates)
                return;
            this.selectionBox?.startPoint.set(normalizedCoordinates.x, normalizedCoordinates.y, 0.5);
        };
        this.onPointerMove = (event) => {
            if (!this.enabled || !this.selectionBox)
                return;
            if (event.buttons !== 1)
                return;
            const normalizedCoordinates = this.updateNormalizedDeviceCoordinates(event);
            if (!normalizedCoordinates)
                return;
            this.selectionBox.endPoint.set(normalizedCoordinates.x, normalizedCoordinates.y, 0.5);
            const allSelected = this.selectionBox.select();
            if (this.isSelectionChanged(allSelected)) {
                // Incorrect type definition in three.js
                this.onSelected.emit(allSelected);
                this.lastSelection = allSelected;
            }
        };
    }
    updateCurrentContext(camera, scene, renderer) {
        if (!this.helper) {
            this.helper = new SelectionHelperFixed(renderer, 'zee_selectionbox');
            this.helper.element.style.position = 'absolute';
            this.helper.element.style.zIndex = '10000';
            this.helper.element.style.backgroundColor = 'rgba(1,1,1,0.3)';
        }
        if (!this.selectionBox) {
            this.selectionBox = new SelectionBox(camera, scene);
        }
        this.selectionBox.camera = camera;
        this.selectionBox.scene = scene;
        this.helper.renderer = renderer;
        this.renderer = renderer;
        this.helper.element.style.visibility = this.enabled ? 'visible' : 'hidden';
    }
    updateNormalizedDeviceCoordinates(event) {
        if (!this.renderer)
            return null;
        const rect = this.renderer.domElement.getBoundingClientRect();
        this.normalizedDeviceCoordinates.set(((event.clientX - rect.left) / rect.width) * 2 - 1, -((event.clientY - rect.top) / rect.height) * 2 + 1);
        return this.normalizedDeviceCoordinates;
    }
    isSelectionChanged(newSelection) {
        if (newSelection.length !== this.lastSelection.length) {
            return true;
        }
        const newSet = new Set(newSelection);
        return this.lastSelection.some(item => !newSet.has(item));
    }
    dispose() {
        this.helper?.dispose();
    }
}
