import * as THREE from 'three';
import { Behavior, Event, nextUserEvent, Observable, useCanvas, useOnBeforeRender } from '@zcomponent/core';
import { useCamera } from '../scenecontext';
import { degToRad } from 'three/src/math/MathUtils';
const zee = new THREE.Vector3(0, 0, 1);
const euler = new THREE.Euler();
const q0 = new THREE.Quaternion();
const q1 = new THREE.Quaternion(-Math.sqrt(0.5), 0, 0, Math.sqrt(0.5));
/**
 * Rotate and move the camera to match the device's orientation with respect to gravity.
 *
 *
 * @zbehavior
 * @zicon 360
 * @zparents three/Object3D/Camera/**
 */
export class DeviceOrientation extends Behavior {
    /**
     * Constructs a new DeviceOrientation Behavior.
     * @param contextManager - The context manager.
     * @param instance - The Camera instance.
     * @param constructorProps - The properties required to construct the DeviceOrientation Behavior.
     */
    constructor(contextManager, instance, constructorProps) {
        super(contextManager, instance);
        this.constructorProps = constructorProps;
        this.onPermissionDenied = new Event();
        /**
         * Allow users on devices without any motion data (e.g. no support or no permission) to
         * swipe or drag on the screen to rotate the view in all dimensions.
         *
         * @zui
         * @zdefault true
         */
        this.gestureFallback = new Observable(true);
        /**
         * Allow users on devices to swipe or drag on the screen to rotate the left-right axis of the view.
         *
         * @zui
         * @zdefault true
         */
        this.gestureDirection = new Observable(true);
        this._domEventsBound = false;
        this._isIOS = false;
        this._gestureXOffset = 0;
        this._gestureYOffset = 0;
        this._frame = (dt) => {
            if (useCamera(this.contextManager).value !== this.instance.element)
                return;
            let alpha = this._gestureXOffset;
            let beta = this._gestureYOffset + degToRad(90);
            let gamma = 0;
            const evt = this._latestOrientationEvent;
            if (evt) {
                alpha += evt.alpha ? degToRad(evt.alpha + (this._isIOS ? 0 : -90)) : 0;
                beta = evt.beta ? degToRad(evt.beta) : 0;
                gamma += evt.gamma ? degToRad(evt.gamma) : 0;
            }
            let orientation = 0;
            if (window.orientation !== undefined) {
                orientation = degToRad(window.orientation);
            }
            else {
                orientation = degToRad(window.screen.orientation.angle);
                if (this._isIOS)
                    orientation *= -1;
            }
            euler.set(beta, alpha, -gamma, 'YXZ');
            this.instance.element.quaternion.setFromEuler(euler); // orient the device
            this.instance.element.quaternion.multiply(q1); // camera looks out the back of the device, not the top
            this.instance.element.quaternion.multiply(q0.setFromAxisAngle(zee, -orientation)); // adjust for screen orientation
        };
        this._updateDOMEvents = () => {
            if (this.enabledResolved.value && useCamera(this.contextManager).value === this.instance.element) {
                this._activateDOMEvents();
                return;
            }
            this._deactivateDOMEvents();
        };
        this._deviceOrientation = (evt) => {
            this._latestOrientationEvent = evt;
        };
        this._lastDragPosition = [undefined, undefined];
        this._pointerMove = (evt) => {
            if (!evt.isPrimary || evt.buttons === 0)
                return;
            if (this._lastDragPosition[0] !== undefined && this._lastDragPosition[1] !== undefined) {
                if (this.gestureDirection.value || (this.gestureFallback.value && this._latestOrientationEvent === undefined)) {
                    this._gestureXOffset += (evt.clientX - this._lastDragPosition[0]) * 0.002;
                }
                if (this.gestureFallback.value && this._latestOrientationEvent === undefined) {
                    this._gestureYOffset += (evt.clientY - this._lastDragPosition[1]) * 0.002;
                    this._gestureYOffset = Math.min(this._gestureYOffset, Math.PI / 2);
                    this._gestureYOffset = Math.max(this._gestureYOffset, Math.PI / -2);
                }
            }
            this._lastDragPosition = [evt.clientX, evt.clientY];
        };
        this._pointerUp = () => {
            this._lastDragPosition[0] = undefined;
            this._lastDragPosition[1] = undefined;
        };
        this.register(this.enabledResolved, this._updateDOMEvents, { bindWhenDisabled: true });
        this.register(useOnBeforeRender(this.contextManager), this._frame);
        this._isIOS = navigator.userAgent.indexOf('iPhone OS') >= 0;
        if (constructorProps.requestPermission ?? true) {
            nextUserEvent(this.contextManager).then(async () => {
                if (window.DeviceOrientationEvent && typeof window.DeviceOrientationEvent.requestPermission === 'function') {
                    const state = await window.DeviceOrientationEvent.requestPermission();
                    if (state !== 'granted')
                        this.onPermissionDenied.emit();
                }
            });
        }
    }
    async _activateDOMEvents() {
        if (this._domEventsBound)
            return;
        this._domEventsBound = true;
        window.addEventListener('deviceorientation', this._deviceOrientation);
        if (this.gestureDirection.value || this.gestureFallback.value) {
            const canvas = useCanvas(this.contextManager);
            canvas.addEventListener('pointermove', this._pointerMove);
            canvas.addEventListener('pointerup', this._pointerUp);
        }
    }
    _deactivateDOMEvents() {
        if (!this._domEventsBound)
            return;
        this._domEventsBound = false;
        this._lastDragPosition[0] = undefined;
        this._lastDragPosition[1] = undefined;
        window.removeEventListener('deviceorientation', this._deviceOrientation);
        const canvas = useCanvas(this.contextManager);
        canvas.removeEventListener('pointermove', this._pointerMove);
        canvas.removeEventListener('pointerup', this._pointerUp);
    }
    /**
     * Disposes the DeviceOrientation Behavior.
     */
    dispose() {
        this._deactivateDOMEvents();
        return super.dispose();
    }
}
