import { ActionBehavior } from '@zcomponent/core';
import { Camera } from '../components/cameras/Camera';
/**
 * Switches the current active camera.
 *
 * The camera that is marked as `active` is used by the renderer to render the scene.
 *
 * You can also:
 * - Use the `activate` method of the camera component.
 * - Use `activateAtStart` property of the camera component.
 * @zbehavior
 * @zicon videocam
 * @zgroup Actions
 */
export class ActivateCamera extends ActionBehavior {
    perform() {
        const zcomp = this.getZComponentInstance();
        const camera = zcomp.entityByID.get(this.camera);
        if (!camera || !(camera instanceof Camera))
            return;
        camera.activate();
    }
}
