export class Menu {
    constructor(items) {
        this.dom = document.createElement('div');
        this._ul = document.createElement('ul');
        this.dom.classList.add('zee-preview-menu');
        const button = document.createElement('button');
        button.innerHTML = menuIcon;
        button.addEventListener('click', evt => this.show(evt));
        this.dom.appendChild(button);
        const closer = document.createElement('div');
        closer.addEventListener('click', evt => this.hide());
        closer.classList.add('zee-preview-menu-closer');
        this.dom.appendChild(closer);
        this._ul = document.createElement('ul');
        this.dom.appendChild(this._ul);
        for (const item of items) {
            const li = document.createElement('li');
            this._ul.appendChild(li);
            if (item.isCheckbox) {
                const checkbox = document.createElement('input');
                checkbox.type = 'checkbox';
                checkbox.style.marginLeft = '0';
                checkbox.style.cursor = 'pointer';
                checkbox.checked = item.checked || false;
                checkbox.addEventListener('change', () => {
                    if (item.onToggle) {
                        item.onToggle(checkbox.checked);
                    }
                    this.hide();
                });
                li.appendChild(checkbox);
                const label = document.createElement('span');
                label.innerText = item.title;
                li.appendChild(label);
                li.addEventListener('click', evt => {
                    evt.stopPropagation();
                    checkbox.checked = !checkbox.checked;
                    if (item.onToggle) {
                        item.onToggle(checkbox.checked);
                    }
                    this.hide();
                });
                checkbox.addEventListener('click', evt => {
                    evt.stopPropagation();
                });
            }
            else {
                li.innerText = item.title;
                li.addEventListener('click', evt => {
                    evt.stopPropagation();
                    this.hide();
                    item.onClick?.();
                });
            }
        }
    }
    show(evt) {
        const x = evt.clientX;
        const y = evt.clientY;
        const rects = this._ul.getBoundingClientRect();
        const anchorRight = window.innerWidth < x + 300;
        const anchorBottom = window.innerHeight < y + 500;
        this.dom.classList.add('zee-preview-menu-open');
        if (anchorRight) {
            this._ul.style.right = (window.innerWidth - x).toString() + 'px';
            this._ul.style.left = '';
        }
        else {
            this._ul.style.right = '';
            this._ul.style.left = x.toString() + 'px';
        }
        if (anchorBottom) {
            this._ul.style.top = '';
            this._ul.style.bottom = (window.innerHeight - y).toString() + 'px';
        }
        else {
            this._ul.style.top = y.toString() + 'px';
            this._ul.style.bottom = '';
        }
    }
    hide() {
        this.dom.classList.remove('zee-preview-menu-open');
    }
}
const menuIcon = '<svg xmlns="http://www.w3.org/2000/svg" height="20" width="20"><path d="M3 14.5V13h14v1.5Zm0-3.75v-1.5h14v1.5ZM3 7V5.5h14V7Z"/></svg>';
