import { Observable } from '@zcomponent/core';
/**
 * Manages the display settings for various Three.js helper objects within a design-time environment.
 * Provides observables to control the visibility of camera and raycaster helpers.
 *
 */
export class ThreeHelperContext {
    constructor() {
        /**
         * Observable property to control the visibility of camera helpers at design time.
         */
        this.showCameraHelpersAtDesignTime = new Observable(true);
        /**
         * Observable property to control the visibility of raycaster helpers at design time.
         */
        this.showRaycasterHelpersAtDesignTime = new Observable(true);
    }
}
/**
 * Utility function to access the observable property for showing camera helpers at design time within a ContextManager.
 *
 * @param {ContextManager} mgr - The context manager instance.
 */
export function useShowCameraHelpersAtDesignTime(mgr) {
    return mgr.get(ThreeHelperContext).showCameraHelpersAtDesignTime;
}
/**
 * Utility function to access the observable property for showing raycaster helpers at design time within a ContextManager.
 *
 * @param {ContextManager} mgr - The context manager instance.
 * @return {Observable<boolean>} The observable property for showing raycaster helpers.
 */
export function useShowRaycasterHelpersAtDesignTime(mgr) {
    return mgr.get(ThreeHelperContext).showRaycasterHelpersAtDesignTime;
}
