import { Component } from '@zcomponent/core';
import { WebXRContext } from '../webxrcontext';
/**
 * @zcomponent
 * @ztag three/WebXRSettings
 * @zicon settings
 * @zgroup Deprecated
 * @zparents three/Object3D/Group/**
 */
export class WebXRSettings extends Component {
    /**
     * Controls whether the WebXR session should be started when the component is created.
     * @param contextManager - The context manager.
     * @param constructorProps - The constructor properties.
     */
    constructor(contextManager, constructorProps) {
        super(contextManager, constructorProps);
        this._context = this.contextManager.get(WebXRContext);
        const context = contextManager.get(WebXRContext);
        if (constructorProps.startOnLaunch)
            context.startOnLaunch(constructorProps.startOnLaunch);
    }
}
