import { isDesignTime, Observable } from '@zcomponent/core';
import { Group } from '../Group';
import * as THREE from 'three';
/**
 * Place this component within a `WebXRMovementGroup`. The contents of this group will then be shown to the user when they're choosing
 * a destination for a 'Teleport' movement.
 *
 * Root element: [THREE.Group](https://threejs.org/docs/index.html#api/en/objects/Group)
 *
 * @zcomponent
 * @zicon location_on
 * @zgroup Deprecated
 * @ztag three/Object3D/Group/WebXRMovementPreviewGroup
 * @zparents three/Object3D/Group/WebXRMovementGroup
 */
export class WebXRMovementPreviewGroup extends Group {
    constructor(contextManager, constructorProps) {
        const innerGroup = new THREE.Group();
        super(contextManager, constructorProps, innerGroup);
        /**
         * Whether or not to show the contents of this group when the user is choosing a destination for a 'Teleport' movement.
         */
        this.previewAtDesignTime = new Observable(true);
        this.innerGroup = innerGroup;
        this.innerGroup.matrixAutoUpdate = false;
        this.innerGroup.visible = (constructorProps.previewAtDesignTime ?? true) && isDesignTime(contextManager);
        this.element.add(innerGroup);
    }
}
