import { ActionBehavior } from '@zcomponent/core';
import { WebXRContext, XRSessionMode } from '../webxrcontext';
/**
 * Launches a WebXR session.
 *
 * @zbehavior
 * @zicon vrpano
 * @zgroup Deprecated
 */
export class LaunchWebXRSession extends ActionBehavior {
    constructor() {
        super(...arguments);
        /**
         * The mode of the session to launch.
         * @zprop
         * @zgroup Actions
         * @zdefault immersive-vr
         */
        this.mode = XRSessionMode['immersive-vr'];
    }
    /**
     * Launches a WebXR session.
     */
    perform() {
        const context = this.contextManager.get(WebXRContext);
        context.startSession(this.mode ?? XRSessionMode['immersive-vr']);
    }
}
