import { Observable } from '@zcomponent/core';
import { Object3D } from '../Object3D';
/**
 * Base class for all lights.
 */
export class Light extends Object3D {
    constructor(contextManager, props, element) {
        super(contextManager, props, element);
        this.element = element;
        /**
         * Color of the light.
         * @zprop
         * @zgroup Light
         * @zgrouppriority 5
         * @zdefault [1, 1, 1]
         * @ztype color-norm-rgb-linear
         */
        this.color = new Observable([1, 1, 1], v => this.element.color.setRGB(...v));
        /**
         * Numeric value of the light's strength/intensity. Default is 1
         * @zprop
         * @zgroup Light
         * @zgrouppriority 5
         * @zdefault 1
         */
        this.intensity = new Observable(1, v => {
            this.element.intensity = v;
        });
        /**
         * Normal bias for shadow mapping, useful for reducing shadow acne.
         * @zprop
         * @zgroup LightShadow
         * @zgrouppriority 10
         * @zdefault 0
         */
        this.normalBias = new Observable(0, v => {
            this.element.shadow.normalBias = v;
            this.element.shadow.needsUpdate = true;
        });
        /**
         * Radius to blur the edges of the shadow. High values may cause banding effects.
         * @zprop
         * @zgroup LightShadow
         * @zgrouppriority 10
         * @zdefault 1
         */
        this.radius = new Observable(1, v => {
            this.element.shadow.radius = v;
            this.element.shadow.needsUpdate = true;
        });
        /**
         * Bias for shadow mapping to reduce shadow artifacts.
         * @zprop
         * @zgroup LightShadow
         * @zgrouppriority 10
         * @zdefault 0
         */
        this.bias = new Observable(0, v => {
            this.element.shadow.bias = v;
            this.element.shadow.needsUpdate = true;
        });
        /**
         * The number of samples to use when blurring a VSM shadow map.
         * @zprop
         * @zgroup LightShadow
         * @zgrouppriority 10
         * @zdefault 8
         */
        this.blurSamples = new Observable(8, v => {
            this.element.shadow.blurSamples = v;
            this.element.shadow.needsUpdate = true;
        });
        this.element.shadow?.mapSize.fromArray(props.shadowMapSize ?? [1024, 1024]);
    }
    /**
     * Disposes the light and releases all resources.
     */
    dispose() {
        this.element.dispose();
        return super.dispose();
    }
}
