import { Observable } from '@zcomponent/core';
import * as THREE from 'three';
import { Light } from './Light';
/**
 * A light that's emitted in all directions from a point in space.
 *
 * Root element: [THREE.PointLight](https://threejs.org/docs/index.html?q=SpotLig#api/en/lights/PointLight)
 *
 * @zcomponent
 * @zgroup Lights
 * @zicon light
 * @ztag three/Object3D/Light/PointLight
 * @zparents three/Object3D/Group/**
 */
export class PointLight extends Light {
    constructor(contextManager, props) {
        super(contextManager, props, new THREE.PointLight());
        /**
         * The amount the light dims along the distance of the light.
         *
         * @zprop
         * @zgroup Light
         * @zgrouppriority 5
         * @zdefault 1
         */
        this.decay = new Observable(1, v => (this.element.decay = v));
    }
}
