import * as THREE from 'three';
export class GridMaterial extends THREE.ShaderMaterial {
    constructor(parameters) {
        const shaderUniforms = {
            cellSize: { value: parameters.cellSize ?? 0.5 },
            sectionSize: { value: parameters.sectionSize ?? 1 },
            fadeDistance: { value: parameters.fadeDistance ?? 100 },
            fadeStrength: { value: parameters.fadeStrength ?? 1 },
            fadeFrom: { value: parameters.fadeFrom ?? 1 },
            cellThickness: { value: parameters.cellThickness ?? 0.5 },
            sectionThickness: { value: parameters.sectionThickness ?? 1 },
            cellColor: { value: new THREE.Color(parameters.cellColor ?? '#000000') },
            sectionColor: { value: new THREE.Color(parameters.sectionColor ?? '#2080ff') },
            infiniteGrid: { value: parameters.infiniteGrid ?? false },
            followCamera: { value: parameters.followCamera ?? false },
            worldCamProjPosition: { value: new THREE.Vector3() },
            worldPlanePosition: { value: new THREE.Vector3() },
        };
        super({
            uniforms: shaderUniforms,
            vertexShader: `
        varying vec3 localPosition;
        varying vec4 worldPosition;

        uniform vec3 worldCamProjPosition;
        uniform vec3 worldPlanePosition;
        uniform float fadeDistance;
        uniform bool infiniteGrid;
        uniform bool followCamera;

        void main() {
          localPosition = position;
          if (infiniteGrid) localPosition *= 1.0 + fadeDistance;

          worldPosition = modelMatrix * vec4(localPosition, 1.0);
          if (followCamera) {
            worldPosition.xyz += (worldCamProjPosition - worldPlanePosition);
            localPosition = (inverse(modelMatrix) * worldPosition).xyz;
          }

          gl_Position = projectionMatrix * viewMatrix * worldPosition;
        }
      `,
            fragmentShader: `
        varying vec3 localPosition;
        varying vec4 worldPosition;

        uniform vec3 worldCamProjPosition;
        uniform float cellSize;
        uniform float sectionSize;
        uniform vec3 cellColor;
        uniform vec3 sectionColor;
        uniform float fadeDistance;
        uniform float fadeStrength;
        uniform float fadeFrom;
        uniform float cellThickness;
        uniform float sectionThickness;

        float getGrid(float size, float thickness) {
          vec2 r = localPosition.xz / size;
          vec2 grid = abs(fract(r - 0.5) - 0.5) / fwidth(r);
          float line = min(grid.x, grid.y) + 1.0 - thickness;
          return 1.0 - min(line, 1.0);
        }

        void main() {
          float g1 = getGrid(cellSize, cellThickness);
          float g2 = getGrid(sectionSize, sectionThickness);

          vec3 from = worldCamProjPosition * vec3(fadeFrom);
          float dist = distance(from, worldPosition.xyz);
          float d = 1.0 - min(dist / fadeDistance, 1.0);
          vec3 color = mix(cellColor, sectionColor, min(1.0, sectionThickness * g2));

          gl_FragColor = vec4(color, (g1 + g2) * pow(d, fadeStrength));
          gl_FragColor.a = mix(0.75 * gl_FragColor.a, gl_FragColor.a, g2);
          if (gl_FragColor.a <= 0.0) discard;

					#include <tonemapping_fragment>
					  #include <${Number(THREE.REVISION) >= 154 ? 'colorspace_fragment' : 'encodings_fragment'}>
        }
      `,
            transparent: true,
            side: parameters.side ?? THREE.BackSide,
            extensions: {
                derivatives: true,
            },
        });
    }
}
export class Grid extends THREE.Mesh {
    constructor(props) {
        const geometry = new THREE.PlaneGeometry(10, 10);
        geometry.rotateX(-Math.PI / 2);
        const material = new GridMaterial(props);
        super(geometry, material);
        this.dispose = () => {
            const material = this.material;
            material.dispose();
            this.geometry.dispose();
        };
        const plane = new THREE.Plane();
        const upVector = new THREE.Vector3(0, 1, 0);
        const zeroVector = new THREE.Vector3(0, 0, 0);
        const update = (camera) => {
            plane.setFromNormalAndCoplanarPoint(upVector, zeroVector).applyMatrix4(this.matrixWorld);
            const gridMaterial = this.material;
            const worldCamProjPosition = gridMaterial.uniforms.worldCamProjPosition;
            const worldPlanePosition = gridMaterial.uniforms.worldPlanePosition;
            plane.projectPoint(camera.position, worldCamProjPosition.value);
            worldPlanePosition.value.set(0, 0, 0).applyMatrix4(this.matrixWorld);
        };
        this.onBeforeRender = (renderer, scene, camera, geometry, material, group) => {
            update(camera);
        };
        this.frustumCulled = false;
    }
}
