import { TriggerShape } from '../ITrigger';
import { Context } from '@zcomponent/core';
/**
 * A manager for collision detection between triggers and colliders.
 * @zcontext
 */
export class CollisionManagerContext extends Context {
    constructor(contextManager, props) {
        super(contextManager, props);
        this.collisionHandlers = {
            [TriggerShape.Cube]: {
                [TriggerShape.Cube]: this.cubeCubeCollision.bind(this),
                [TriggerShape.Sphere]: this.cubeSphereCollision.bind(this),
                [TriggerShape.Plane]: this.cubePlaneCollision.bind(this),
                [TriggerShape.Point]: this.pointCubeCollision.bind(this),
            },
            [TriggerShape.Sphere]: {
                [TriggerShape.Cube]: this.cubeSphereCollision.bind(this),
                [TriggerShape.Sphere]: this.sphereSphereCollision.bind(this),
                [TriggerShape.Plane]: this.planeSphereCollision.bind(this),
                [TriggerShape.Point]: this.pointSphereCollision.bind(this),
            },
            [TriggerShape.Plane]: {
                [TriggerShape.Cube]: this.planeCubeCollision.bind(this),
                [TriggerShape.Sphere]: this.planeSphereCollision.bind(this),
                [TriggerShape.Plane]: this.planePlaneCollision.bind(this),
                [TriggerShape.Point]: this.pointPlaneCollision.bind(this),
            },
            [TriggerShape.Point]: {
                [TriggerShape.Cube]: this.pointCubeCollision.bind(this),
                [TriggerShape.Sphere]: this.pointSphereCollision.bind(this),
                [TriggerShape.Plane]: this.pointPlaneCollision.bind(this),
                [TriggerShape.Point]: this.pointPointCollision.bind(this),
            },
        };
    }
    /**
     * Checks whether two shapes are colliding.
     * @param shape1 - The first shape to check for collision.
     * @param shape2 - The second shape to check for collision.
     * @returns - Whether the two shapes are colliding.
     */
    isColliding(shape1, shape2) {
        const handler = this.collisionHandlers[shape1.shape]?.[shape2.shape];
        if (handler) {
            return handler(shape1, shape2);
        }
        return false;
    }
    unexpectedShapes(shape1, shape2) {
        console.warn('unexpected shapes', shape1.shape, shape2.shape);
        return false;
    }
    handleArguments(shape1, shape2, shapeType1, shapeType2, callback) {
        if (shape1.shape === shapeType1 && shape2.shape === shapeType2) {
            return callback(shape1, shape2);
        }
        else if (shape1.shape === shapeType2 && shape2.shape === shapeType1) {
            return callback(shape2, shape1);
        }
        return this.unexpectedShapes(shape1, shape2);
    }
    planePlaneCollision(plane1, plane2) {
        return this.handleArguments(plane1, plane2, TriggerShape.Plane, TriggerShape.Plane, (p1, p2) => p1.worldBoundingBox.intersectsOBB(p2.worldBoundingBox));
    }
    planeCubeCollision(plane, cube) {
        return this.handleArguments(plane, cube, TriggerShape.Plane, TriggerShape.Cube, (p, c) => c.worldBoundingBox.intersectsOBB(p.worldBoundingBox));
    }
    planeSphereCollision(plane, sphere) {
        return this.handleArguments(plane, sphere, TriggerShape.Plane, TriggerShape.Sphere, (p, s) => p.worldBoundingBox.intersectsSphere(s.worldBoundingSphere));
    }
    cubeCubeCollision(cube1, cube2) {
        return this.handleArguments(cube1, cube2, TriggerShape.Cube, TriggerShape.Cube, (c1, c2) => c2.worldBoundingBox.intersectsOBB(c1.worldBoundingBox));
    }
    cubeSphereCollision(cube, sphere) {
        return this.handleArguments(cube, sphere, TriggerShape.Cube, TriggerShape.Sphere, (c, s) => c.worldBoundingBox.intersectsSphere(s.worldBoundingSphere));
    }
    sphereSphereCollision(sphere1, sphere2) {
        return this.handleArguments(sphere1, sphere2, TriggerShape.Sphere, TriggerShape.Sphere, (s1, s2) => s1.worldBoundingSphere.intersectsSphere(s2.worldBoundingSphere));
    }
    pointPointCollision(point1, point2) {
        return this.handleArguments(point1, point2, TriggerShape.Point, TriggerShape.Point, (p1, p2) => p1.worldPosition.equals(p2.worldPosition));
    }
    pointCubeCollision(point, cube) {
        return this.handleArguments(point, cube, TriggerShape.Point, TriggerShape.Cube, (p, c) => c.worldBoundingBox.containsPoint(p.worldPosition));
    }
    pointSphereCollision(point, sphere) {
        return this.handleArguments(point, sphere, TriggerShape.Point, TriggerShape.Sphere, (p, s) => s.worldBoundingSphere.containsPoint(p.worldPosition));
    }
    pointPlaneCollision(point, plane) {
        return this.handleArguments(point, plane, TriggerShape.Point, TriggerShape.Plane, (p, pl) => pl.worldBoundingBox.containsPoint(p.worldPosition));
    }
    cubePlaneCollision(cube, plane) {
        return this.handleArguments(cube, plane, TriggerShape.Cube, TriggerShape.Plane, (c, pl) => c.worldBoundingBox.intersectsOBB(pl.worldBoundingBox));
    }
}
