import * as THREE from 'three';
import { CameraHelper } from './internal/CameraHelper';
export class CameraViewportRenderer {
    constructor(helpersGroup, size = 256) {
        this.helpersGroup = helpersGroup;
        this.size = size;
        this.camera = null;
        this.padding = 12;
        this.viewport = new THREE.Vector4();
    }
    calculateAspectRatio(camera, renderer) {
        if (camera instanceof THREE.PerspectiveCamera) {
            return camera.aspect;
        }
        else if (camera instanceof THREE.OrthographicCamera) {
            return camera.right / camera.top;
        }
        return renderer.domElement.clientWidth / renderer.domElement.clientHeight;
    }
    setCamera(camera) {
        this.camera = camera;
    }
    render(scene, renderer) {
        if (!scene || !this.camera)
            return;
        // Handle helper group
        const helperGroupParent = this.helpersGroup.parent;
        helperGroupParent?.remove(this.helpersGroup);
        const aspectRatio = this.calculateAspectRatio(this.camera, renderer);
        const cameraLineHelper = this.camera.children.find(c => c instanceof CameraHelper);
        const previousCameraLineHelperVisible = cameraLineHelper?.material.visible;
        if (cameraLineHelper)
            cameraLineHelper.material.visible = false;
        renderer.clearDepth();
        this.calculateAndSetViewport(renderer, aspectRatio);
        this.renderScene(renderer, scene);
        // Reset states
        helperGroupParent?.add(this.helpersGroup);
        if (cameraLineHelper && previousCameraLineHelperVisible !== undefined) {
            cameraLineHelper.material.visible = previousCameraLineHelperVisible;
        }
    }
    calculateAndSetViewport(renderer, aspectRatio) {
        const [viewportWidth, viewportHeight] = aspectRatio > 1 ? [this.size - this.padding * 2, this.size / aspectRatio - this.padding * 2] : [this.size * aspectRatio - this.padding * 2, this.size - this.padding * 2];
        const height = renderer.domElement.clientHeight;
        this.viewport.set(this.padding, height - viewportHeight - this.padding, viewportWidth, viewportHeight);
    }
    renderScene(renderer, scene) {
        if (!this.camera)
            return;
        const originalViewport = new THREE.Vector4();
        renderer.getViewport(originalViewport);
        const originalClearColor = new THREE.Color();
        const originalClearAlpha = renderer.getClearAlpha();
        // Outline settings
        const outlineMargin = 2;
        const outlineX = this.viewport.x - outlineMargin;
        const outlineY = this.viewport.y - outlineMargin;
        const outlineWidth = this.viewport.z + outlineMargin * 2;
        const outlineHeight = this.viewport.w + outlineMargin * 2;
        // Render the outline
        renderer.setScissor(outlineX, outlineY, outlineWidth, outlineHeight);
        renderer.setViewport(outlineX, outlineY, outlineWidth, outlineHeight);
        renderer.setScissorTest(true);
        renderer.setClearColor(0x252525, 1); // Outline color
        renderer.clear();
        // Render the scene with transparent background
        renderer.setScissor(this.viewport.x, this.viewport.y, this.viewport.z, this.viewport.w);
        renderer.setViewport(this.viewport.x, this.viewport.y, this.viewport.z, this.viewport.w);
        renderer.setClearColor(0x000000, 0);
        renderer.clear(true, false, false);
        renderer.render(scene, this.camera);
        renderer.setScissorTest(false);
        renderer.setViewport(originalViewport.x, originalViewport.y, originalViewport.z, originalViewport.w);
        renderer.setClearColor(originalClearColor, originalClearAlpha);
    }
}
