import { Observable } from '@zcomponent/core';
import * as THREE from 'three';
import { UnrealBloomPass as THREEBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass';
import { Pass } from './Pass';
/**
 * A bloom pass component.
 *
 * Bloom is a postprocessing effect that adds a glow to bright areas of the scene.
 *
 *
 * @zcomponent
 * @zgroup Post Processing
 * @zicon postprocess
 * @ztag three/PostProcessing/UnrealBloomPass
 * @zparents three/Object3D/Group/**
 */
export class _UnrealBloomPass extends Pass {
    constructor(contextManager, props) {
        super(contextManager, props, new THREEBloomPass(new THREE.Vector2(1024, 1024), 5, 0, 0));
        /**
         * The strength of the bloom.
         * @zprop
         * @zgroup UnrealBloomPass
         * @zgrouppriority 20
         * @zdefault 5
         */
        this.strength = new Observable(5, v => (this.root.strength = v));
        /**
         * The radius of the bloom.
         * @zprop
         * @zgroup UnrealBloomPass
         * @zgrouppriority 20
         * @zdefault 0
         */
        this.radius = new Observable(0, v => (this.root.radius = v));
        /**
         * The threshold of the bloom.
         * @zprop
         * @zgroup UnrealBloomPass
         * @zgrouppriority 20
         * @zdefault 0
         */
        this.threshold = new Observable(0, v => (this.root.threshold = v));
    }
}
