import { OBB } from 'three/examples/jsm/math/OBB';
import { Trigger } from './Trigger';
/**
 * An oriented bounding box trigger component.
 */
export class OBBTrigger extends Trigger {
    /**
     * Constructs an oriented bounding box trigger.
     * @param ctx - The context manager.
     * @param props - The properties for trigger construction, including shape.
     */
    constructor(ctx, props) {
        super(ctx, { ...props });
        /**
         * The world-space oriented bounding box of the trigger.
         */
        this.worldBoundingBox = new OBB();
        this.previewMesh.geometry.computeBoundingBox();
    }
    /**
     * Updates the world-space bounding box based on the trigger's current state.
     */
    update() {
        this.worldBoundingBox.fromBox3(this.previewMesh.geometry.boundingBox);
        this.worldBoundingBox.applyMatrix4(this.previewMesh.matrixWorld);
    }
}
