export class InlineCheckboxButton extends HTMLInputElement {
    constructor(options) {
        super();
        this.isKeyDown = false;
        this.handleKeyDown = (event) => {
            if (event.key === this.toggleKey && !this.isKeyDown) {
                this.isKeyDown = true;
                this.checked = !this.baseChecked;
                this.updateIcon();
                this.dispatchEvent(new Event('change'));
            }
        };
        this.handleKeyUp = (event) => {
            if (event.key === this.toggleKey) {
                this.isKeyDown = false;
                this.checked = this.baseChecked;
                this.updateIcon();
                this.dispatchEvent(new Event('change'));
            }
        };
        this.type = 'checkbox';
        this.baseChecked = options.checked || false;
        this.checked = this.baseChecked;
        this.toggleKey = options.toggleKey;
        this.style.display = 'none';
        this.label = document.createElement('label');
        this.label.style.display = 'flex';
        this.label.style.alignItems = 'center';
        this.label.style.justifyContent = 'center';
        this.label.style.position = 'relative';
        this.label.style.cursor = 'pointer';
        this.label.title = options.title;
        this.iconOn = this.createIcon(options.icon);
        this.iconOff = options.iconOff ? this.createIcon(options.iconOff) : this.iconOn;
        this.label.appendChild(this.checked ? this.iconOn : this.iconOff);
        this.label.appendChild(this);
        this.addEventListener('change', () => {
            if (!this.isKeyDown) {
                this.baseChecked = this.checked;
            }
            this.updateIcon();
            if (options.onToggle) {
                options.onToggle(this.checked);
            }
        });
        this.label.addEventListener('mouseover', () => this.updateHoverState(true));
        this.label.addEventListener('mouseout', () => this.updateHoverState(false));
        if (this.toggleKey) {
            document.addEventListener('keydown', this.handleKeyDown);
            document.addEventListener('keyup', this.handleKeyUp);
        }
        this.updateIcon();
    }
    createIcon(icon) {
        const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
        svg.setAttribute('viewBox', '0 0 24 24');
        svg.setAttribute('width', '18');
        svg.setAttribute('height', '18');
        svg.innerHTML = icon;
        return svg;
    }
    updateIcon() {
        const currentIcon = this.checked ? this.iconOn : this.iconOff;
        if (this.label.firstChild !== currentIcon) {
            this.label.replaceChild(currentIcon, this.label.firstChild);
        }
        currentIcon.style.fill = this.checked ? 'var(--highlight)' : 'var(--fontColor)';
    }
    updateHoverState(isHovering) {
        this.label.style.backgroundColor = isHovering ? 'var(--hoverBackground)' : 'transparent';
        if (!this.checked) {
            (this.checked ? this.iconOn : this.iconOff).style.fill = isHovering ? 'var(--hoverForeground)' : 'var(--fontColor)';
        }
    }
    disconnectedCallback() {
        if (this.toggleKey) {
            document.removeEventListener('keydown', this.handleKeyDown);
            document.removeEventListener('keyup', this.handleKeyUp);
        }
    }
}
