export class InlineButton extends HTMLButtonElement {
    constructor(options) {
        super();
        this.style.display = 'flex';
        this.style.alignItems = 'center';
        this.style.justifyContent = 'center';
        this.style.position = 'relative';
        this.style.cursor = 'pointer';
        this.style.border = 'none';
        this.style.backgroundColor = 'transparent';
        this.style.padding = '0';
        this.style.margin = '0';
        this.icon = this.createIcon(options.icon);
        this.appendChild(this.icon);
        this.title = options.title;
        this.addEventListener('click', () => {
            if (options.onClick) {
                options.onClick();
            }
        });
        this.addEventListener('mouseover', () => {
            this.style.backgroundColor = 'var(--hoverBackground)';
            this.icon.style.fill = 'var(--hoverForeground)';
        });
        this.addEventListener('mouseout', () => {
            this.style.backgroundColor = 'transparent';
            this.icon.style.fill = 'var(--fontColor)';
        });
        this.addEventListener('mousedown', () => {
            this.style.backgroundColor = 'var(--activeBackground)';
        });
        this.addEventListener('mouseup', () => {
            this.style.backgroundColor = 'var(--hoverBackground)';
        });
    }
    createIcon(icon) {
        const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
        svg.setAttribute('viewBox', '0 0 24 24');
        svg.setAttribute('width', '18');
        svg.setAttribute('height', '18');
        svg.innerHTML = icon;
        svg.style.fill = 'var(--fontColor)';
        return svg;
    }
}
