export class CheckboxButtonGroup {
    constructor(buttons) {
        this.dom = document.createElement('div');
        this.dom.style.display = 'flex';
        this.dom.style.alignItems = 'center';
        this.dom.style.marginLeft = 'auto';
        this.dom.style.backgroundColor = 'var(--panelBackground)';
        this.dom.style.padding = '6px';
        this.dom.style.borderRadius = '6px';
        this.dom.style.gap = '6px';
        for (const button of buttons) {
            if (button instanceof InlineButton) {
                this.dom.appendChild(button);
            }
            else {
                this.dom.appendChild(button.label);
            }
        }
    }
}
