let _sessionStoreDB;
function getSessionStoreDB() {
    if (!_sessionStoreDB) {
        _sessionStoreDB = new Promise(resolve => {
            const db = indexedDB.open('zcomponent-gltf-session-cache');
            db.onupgradeneeded = function () {
                db.result.createObjectStore('entries');
            };
            db.onsuccess = function (evt) {
                resolve(db.result);
            };
        });
    }
    return _sessionStoreDB;
}
const _sessionCachePromises = new Map();
function getGLTFFromSessionCache(f) {
    let existing = _sessionCachePromises.get(f);
    if (!existing) {
        existing = (async () => {
            if (window.sessionStorage && window.sessionStorage.getItem('zcomponent-gltf-session-cache-' + f) === 'true') {
                const file = await getDBFile(f);
                if (file)
                    return file;
            }
            const req = await fetch(f);
            if (req.status !== 200)
                throw new Error(req.statusText);
            const ab = await req.arrayBuffer();
            setDBFile(f, ab);
            window.sessionStorage.setItem('zcomponent-gltf-session-cache-' + f, 'true');
            return ab;
        })();
        _sessionCachePromises.set(f, existing);
    }
    return existing;
}
async function getDBFile(f) {
    const db = await getSessionStoreDB();
    return await new Promise(resolve => {
        const transaction = db.transaction('entries', 'readonly', { durability: 'relaxed' });
        const ob = transaction.objectStore('entries').get(f);
        ob.onsuccess = () => {
            resolve(ob.result);
        };
        transaction.commit();
    });
}
async function setDBFile(f, ab) {
    const db = await getSessionStoreDB();
    const transaction = db.transaction('entries', 'readwrite', { durability: 'relaxed' });
    transaction.objectStore('entries').put(ab, f);
    return await new Promise(resolve => {
        transaction.oncomplete = () => {
            resolve();
        };
        transaction.commit();
    });
}
