import * as THREE from 'three';
import { Trigger } from './Trigger';
import { TriggerShape } from './ITrigger';
/**
 * A point trigger component.
 *
 * @zcomponent
 * @zgroup Trigger
 * @zicon shapes
 * @zparents three/Object3D/**
 */
export class PointTrigger extends Trigger {
    /**
     * Constructs a point trigger.
     * @param ctx - The context manager.
     * @param props - The properties for trigger construction, including shape.
     */
    constructor(ctx, props) {
        super(ctx, { ...props, shape: TriggerShape.Point });
        /**
         * The world-space position of the trigger.
         */
        this.worldPosition = new THREE.Vector3();
    }
    /**
     * Updates the world-space position based on the trigger's current state.
     */
    update() {
        this.worldPosition.copy(this.previewMesh.position).applyMatrix4(this.previewMesh.matrixWorld);
    }
}
