import { useIsLoaded } from '@zcomponent/core';
import { ZHTMLElement } from '@zcomponent/html/lib/HTMLElement';
import { default as ModelPreview } from './ModelPreview.zcomp';
/**
 * @zcomponent
 */
export class MorphTargetList extends ZHTMLElement {
    constructor(contextManager, props) {
        super(contextManager, props, document.createElement('ul'));
        this._loaded = () => {
            const zcomp = this.getZComponentInstance(ModelPreview);
            const gltf = zcomp.nodes.GLTF;
            this.register(gltf.morphTargetMeshes, this._update);
        };
        this._update = (entries) => {
            const zcomp = this.getZComponentInstance(ModelPreview);
            const gltf = zcomp.nodes.GLTF;
            this.element.innerHTML = '';
            for (const [name, meshes] of entries.entries()) {
                const label = document.createElement('li');
                label.innerText = name;
                this.element.appendChild(label);
                const input = document.createElement('input');
                input.classList.add('zee-input-proportion-range');
                input.type = 'range';
                input.min = '0';
                input.max = '1';
                input.step = 'any';
                input.value = '0';
                input.addEventListener('input', () => {
                    let val = parseFloat(input.value);
                    if (isNaN(val))
                        val = 0;
                    for (const mesh of meshes.values()) {
                        const indx = mesh.morphTargetDictionary?.[name];
                        if (indx === undefined)
                            continue;
                        if (!Array.isArray(mesh.morphTargetInfluences))
                            continue;
                        mesh.morphTargetInfluences[indx] = val;
                    }
                });
                label.appendChild(input);
            }
        };
        const test = document.createElement('li');
        test.innerText = 'Test';
        this.element.appendChild(test);
        this.register(useIsLoaded(contextManager), this._loaded);
    }
}
