import { Observable } from '@zcomponent/core';
import { Object3D } from './Object3D';
import { ThreeSceneContext } from '../scenecontext';
/**
 *
 * Represents a 3D scene, extending the basic Object3D component. This class manages
 * scene-specific settings such as render priority and automatic clearing options, interfacing with the ThreeSceneContext.
 *
 *
 * Root element: [THREE.Scene](https://threejs.org/docs/index.html#api/en/scenes/Scene)
 *
 * @zcomponent
 * @zicon group
 * @zgroup Advanced
 * @ztag three/Object3D/Group/Scene
 * @zparents three/Object3D/Group/**
 */
export class Scene extends Object3D {
    /**
     * Constructs a Scene instance, setting up the scene context and initializing scene properties like render priority.
     *
     * @param {ContextManager} mgr - The context manager.
     * @param {SceneConstructorProps} props - Constructor properties including the render priority for the scene.
     */
    constructor(mgr, props) {
        const [childMgr, ctx] = mgr.fork(ThreeSceneContext);
        ctx.renderPriority.value = props.renderPriority ?? 0;
        ctx.autoClear.value = false;
        ctx.autoClearDepth.value = true;
        super(childMgr, props, ctx.scene);
        /**
         * Observable property to control whether the scene is automatically cleared at the beginning of each render.
         * @zprop
         * @zgroup Scene
         * @zgrouppriority 20
         * @zdefault false
         */
        this.autoClear = new Observable(false, v => {
            if (this._sceneContext)
                this._sceneContext.autoClear.value = v;
        });
        /**
         * Observable property to control whether the depth buffer is automatically cleared at the beginning of each render.
         * @zprop
         * @zgroup Scene
         * @zgrouppriority 20
         * @zdefault true
         */
        this.autoClearDepth = new Observable(true, v => {
            if (this._sceneContext)
                this._sceneContext.autoClearDepth.value = v;
        });
        this._sceneContext = ctx;
    }
    /**
     * Disposes of the scene context and calls the base dispose method.
     */
    dispose() {
        this._sceneContext.dispose();
        this.contextManager.delete(ThreeSceneContext);
        return super.dispose();
    }
}
