import { isDesignTime } from '@zcomponent/core';
import { ThreeContext } from '../../context';
import { useShowCameraHelpersAtDesignTime } from '../../helpercontext';
import { useCamera } from '../../scenecontext';
import { Object3D } from '../Object3D';
import { CameraHelper } from '../../internal/CameraHelper';
/**
 * The base class for all cameras.
 */
export class Camera extends Object3D {
    /**
     * Constructs a new Camera.
     * @param contextManager - The context manager.
     * @param props - The properties required to construct the Camera.
     * @param element - The camera element.
     */
    constructor(contextManager, props, element) {
        super(contextManager, props, element);
        this.element = element;
        this._updateHelpers = () => {
            if (!isDesignTime(this.contextManager) || !useShowCameraHelpersAtDesignTime(this.contextManager).value || this.disposed) {
                this._helper?.dispose();
                this._helper = undefined;
                return;
            }
            if (this._helper)
                return;
            this._helper = new CameraHelper(this.element);
            this.element.add(this._helper);
        };
        if (props.activateAtStart ?? true)
            this.activate();
        contextManager.get(ThreeContext).registerCamera(this.element);
        this.register(useShowCameraHelpersAtDesignTime(this.contextManager), this._updateHelpers);
    }
    /**
     * Activates the camera.
     * @zprop
     * */
    activate() {
        if (!isDesignTime(this.contextManager))
            useCamera(this.contextManager).value = this.element;
    }
    /**
     * Disposes the camera.
     */
    dispose() {
        this.contextManager.get(ThreeContext).unregisterCamera(this.element);
        this._helper?.dispose();
        return super.dispose();
    }
}
