import * as THREE from 'three';
import { Behavior, Observable, registerBehaviorRunAtDesignTime, useOnBeforeRender } from '@zcomponent/core';
import { Quaternion } from 'three';
const _offset = new THREE.Vector3();
const _vec = new THREE.Vector3();
const _quat = new Quaternion();
const _quatInverse = new Quaternion();
const _y = new THREE.Vector3(0, 1, 0);
const _spherical = new THREE.Spherical();
const _sphericalDelta = new THREE.Spherical();
/**
 * Move the camera around a target location at a provided speed.
 *
 * This behavior is registered to run at design time.
 * @zbehavior
 * @zicon 360
 * @zparents three/Object3D/Camera/**
 */
export class AutoOrbit extends Behavior {
    /**
     * Constructs a new AutoOrbit Behavior.
     * @param contextManager - The context manager.
     * @param instance - The Object3D instance.
     */
    constructor(contextManager, instance) {
        super(contextManager, instance);
        /**
         * the initial target of the orbit.
         * @zprop
         * @zdefault [0, 0, 0]
         */
        this.initialTarget = new Observable([0, 0, 0]);
        /**
         * The speed of the orbit.
         * @zprop
         * @zdefault 1
         */
        this.speed = new Observable(1);
        this._frame = (dt) => {
            if (!this.instance.lookAt.value) {
                this.instance.lookAt.value = this.initialTarget.value.slice();
            }
            _sphericalDelta.theta = (this.speed.value * dt) / 1000;
            const node = this.instance.element;
            if (!node || !(node instanceof THREE.Object3D))
                return;
            _quat.setFromUnitVectors(node.up, _y);
            _quatInverse.copy(_quat);
            _quatInverse.invert();
            _vec.set(...this.instance.lookAt.value);
            _offset.copy(node.position).sub(_vec);
            _offset.applyQuaternion(_quat);
            _spherical.setFromVector3(_offset);
            _spherical.theta += _sphericalDelta.theta;
            _offset.setFromSpherical(_spherical);
            _offset.applyQuaternion(_quatInverse);
            node.position.copy(_vec).add(_offset);
            node.lookAt(_vec);
        };
        this.register(useOnBeforeRender(this.contextManager), this._frame);
    }
}
registerBehaviorRunAtDesignTime(AutoOrbit);
