import * as THREE from 'three';
export class SceneStatsMonitor {
    constructor() {
        this.UPDATE_FREQUENCY = 30;
        this._frames = 0;
        this._prevTime = performance.now();
        this._fps = 0;
        this._updateCounter = 0;
        this._cachedStats = null;
        this._needsFullRecalculation = true;
        this._lastCache = {
            fps: 0,
            draws: 0,
            triangles: 0,
            objects: 0,
            vertices: 0,
        };
        this._container = document.createElement('div');
        this._container.style.cssText = `
            position: fixed;
            bottom: var(--edgeSafeGap, 12px);
            left: var(--edgeSafeGap, 12px);
            background: color-mix(in srgb, var(--panelBackground) 85%, transparent);
            color: var(--fontColor);
            font-family: var(--bodyTextFontFamily);
            font-size: var(--bodyTextFontSize);
            padding: 8px 12px;
            border-radius: var(--buttonBorderRadius);
            display: none;
            z-index: 9999;
            border: 1px solid var(--splitterBorder);
            box-shadow: var(--popupShadow);
            backdrop-filter: blur(2px);
            width: fit-content;
            min-width: min-content;
        `;
        this._statsDiv = document.createElement('div');
        this._statsDiv.style.cssText = `
            display: grid;
            grid-template-columns: min-content 1fr;
            gap: 4px 8px;
            line-height: 1.4;
            font-weight: 500;
            white-space: nowrap;
        `;
        this._darkModeObserver = new MutationObserver(this._updateDarkMode.bind(this));
        this._darkModeObserver.observe(document.documentElement, {
            attributes: true,
            attributeFilter: ['data-zeethememode'],
        });
        this._valueElements = {
            fps: this._createStatRow('FPS'),
            draws: this._createStatRow('Draws'),
            objects: this._createStatRow('Objects'),
            triangles: this._createStatRow('Triangles'),
            vertices: this._createStatRow('Vertices'),
        };
        this._updateDarkMode();
        this._container.appendChild(this._statsDiv);
        document.body.appendChild(this._container);
        for (const key of Object.keys(this._valueElements)) {
            this._valueElements[key].textContent = '0';
        }
    }
    _createStatRow(label) {
        const labelDiv = document.createElement('div');
        labelDiv.style.color = 'var(--fontColorSecondary)';
        labelDiv.textContent = `${label}:`;
        const valueDiv = document.createElement('div');
        valueDiv.style.color = 'var(--fontColorSecondary)';
        this._statsDiv.appendChild(labelDiv);
        this._statsDiv.appendChild(valueDiv);
        return valueDiv;
    }
    set visible(visible) {
        this._container.style.display = visible ? 'block' : 'none';
        if (visible)
            this._needsFullRecalculation = true;
    }
    get visible() {
        return this._container.style.display === 'block';
    }
    _updateFPS(now) {
        this._frames++;
        if (now >= this._prevTime + 1000) {
            this._fps = Math.round((this._frames * 1000) / (now - this._prevTime));
            this._prevTime = now;
            this._frames = 0;
        }
    }
    update(renderer, scene, helpersGroup) {
        if (!this.visible)
            return;
        const now = performance.now();
        this._updateFPS(now);
        // _updateCounter === 1 means first frame
        if (++this._updateCounter % this.UPDATE_FREQUENCY === 0 || this._updateCounter === 1) {
            const rendererInfo = renderer.info;
            if (this._needsFullRecalculation || rendererInfo.render.frame !== this._lastCache.objects) {
                this._cachedStats = this._calculateSceneStats(scene, helpersGroup);
                this._needsFullRecalculation = false;
            }
        }
        this._updateDisplay(renderer);
    }
    _isHelper(object, helpersGroup) {
        let parent = object.parent;
        let iterations = 0;
        const MAX_DEPTH = 100;
        while (parent && iterations < MAX_DEPTH) {
            if (parent === helpersGroup)
                return true;
            parent = parent.parent;
            iterations++;
        }
        return false;
    }
    _updateDarkMode() {
        const isDarkMode = document.documentElement.getAttribute('data-zeethememode') !== 'light';
        this._container.style.textShadow = isDarkMode ? '0 1px 2px rgba(0,0,0,0.3)' : 'none';
    }
    _calculateSceneStats(scene, helpersGroup) {
        let objects = 0;
        let vertices = 0;
        let triangles = 0;
        scene.traverseVisible(object => {
            if (this._isHelper(object, helpersGroup))
                return;
            objects++;
            if (!(object instanceof THREE.Mesh))
                return;
            const geometry = object.geometry;
            if (geometry.attributes.position) {
                vertices += geometry.attributes.position.count;
                if (geometry.index !== null) {
                    triangles += geometry.index.count / 3;
                }
                else {
                    triangles += geometry.attributes.position.count / 3;
                }
            }
        });
        return { objects, vertices, triangles };
    }
    _updateIfChanged(key, value, format = String) {
        if (this._lastCache[key] !== value) {
            this._valueElements[key].textContent = format(value);
            this._lastCache[key] = value;
        }
    }
    _updateDisplay(renderer) {
        if (!this._cachedStats || !this.visible)
            return;
        this._updateIfChanged('fps', this._fps);
        this._updateIfChanged('draws', renderer.info.render.calls);
        this._updateIfChanged('triangles', this._cachedStats.triangles, v => Math.round(v).toLocaleString());
        this._updateIfChanged('objects', this._cachedStats.objects);
        this._updateIfChanged('vertices', this._cachedStats.vertices, v => v.toLocaleString());
    }
    invalidateCache() {
        this._needsFullRecalculation = true;
    }
    dispose() {
        this._darkModeObserver.disconnect();
        this._container.remove();
    }
}
