import { ActionBehavior, registerBehaviorRunAtDesignTime } from '@zcomponent/core';
/**
 * Toggles `visible` property of a component.
 *
 * This behavior is registered to run at design time.
 *
 * @see https://threejs.org/docs/?q=object3d#api/en/core/Object3D.visible
 * @zbehavior
 * @zgroup Actions
 * @zicon visibility_off
 * @zparents three/Object3D/**
 */
export class ToggleVisibility extends ActionBehavior {
    constructor(contextManager, instance, props) {
        super(contextManager, instance, props);
        this.instance = instance;
        this.props = props;
    }
    /**
     * Performs the action.
     */
    perform() {
        if (this.constructorProps.visible === undefined)
            this.instance.visible.value = !this.instance.visible.value;
        else
            this.instance.visible.value = this.props.visible === true;
    }
}
registerBehaviorRunAtDesignTime(ToggleVisibility);
