import { Observable } from '@zcomponent/core';
import * as THREE from 'three';
import { Mesh } from './Mesh';
/**
 *
 * A mesh component that receives shadows.
 * Root element: [THREE.Mesh](https://threejs.org/docs/index.html#api/en/objects/Mesh)
 * @zcomponent
 * @zgroup Meshes
 * @zicon capture
 * @ztag three/Object3D/ShadowPlane
 * @zparents three/Object3D/Group/**
 */
export class ShadowPlane extends Mesh {
    constructor(contextManager, props) {
        const material = new THREE.ShadowMaterial({
            polygonOffset: true,
            polygonOffsetFactor: -1.0,
            polygonOffsetUnits: -4.0,
        });
        super(contextManager, {
            ...props,
            geometry: new THREE.PlaneGeometry(10, 10),
            material,
        });
        /**
         * The opacity of the shadow.
         * @zprop
         * @zgroup Appearance
         * @zgrouppriority 11
         * @ztypehint proportion
         * @zdefault 0.2
         */
        this.opacity = new Observable(0.2);
        this._material = material;
        this.register(this.opacity, v => (material.opacity = v));
        this.element.rotateX(Math.PI / -2);
        this.element.receiveShadow = true;
    }
    /**
     * Disposes of the mesh.
     */
    dispose() {
        this._mesh.geometry.dispose();
        this._material.dispose();
        return super.dispose();
    }
}
