import { Observable } from '@zcomponent/core';
import * as THREE from 'three';
import { Light } from './Light';
/**
 * A light that emits light in a single uniform direction with rays parallel to each other. A directional light imitates a light source that is infinitely far away like the sun and is often used to represent sunlight.
 *
 * While the position of a DirectionalLight does not influence the lighting of objects (only its rotation does), the position does influence shadows. For this reason, a DirectionalLight should be positioned such that any geometry that should receive or cast shadows is in front of it.
 *
 * Root element: [THREE.DirectionalLight](https://threejs.org/docs/index.html?q=SpotLig#api/en/lights/DirectionalLight)
 *
 *
 * @zcomponent
 * @zgroup Lights
 * @zicon light
 * @ztag three/Object3D/Light/DirectionalLight
 * @zparents three/Object3D/Group/**
 */
export class DirectionalLight extends Light {
    /**
     * Constructs a DirectionalLight.
     * @param contextManager - The context manager.
     * @param props - The properties required to construct a DirectionalLight.
     */
    constructor(contextManager, props) {
        const light = new THREE.DirectionalLight();
        light.add(light.target);
        light.target.position.set(0, -1, 0);
        super(contextManager, props, light);
        /**
         * Shadow camera's left plane.
         * @zprop
         * @zgroup Shadow Camera
         * @zgrouppriority 4
         * @zdefault -5
         */
        this.shadowCameraLeft = new Observable(-5, v => {
            this.element.shadow.camera.left = v;
            this.element.shadow.camera.updateProjectionMatrix();
        });
        /**
         * Shadow camera's right plane.
         * @zprop
         * @zgroup Shadow Camera
         * @zgrouppriority 4
         * @zdefault 5
         */
        this.shadowCameraRight = new Observable(5, v => {
            this.element.shadow.camera.right = v;
            this.element.shadow.camera.updateProjectionMatrix();
        });
        /**
         * Shadow camera's top plane.
         * @zprop
         * @zgroup Shadow Camera
         * @zgrouppriority 4
         * @zdefault 5
         */
        this.shadowCameraTop = new Observable(5, v => {
            this.element.shadow.camera.top = v;
            this.element.shadow.camera.updateProjectionMatrix();
        });
        /**
         * Shadow camera's bottom plane.
         * @zprop
         * @zgroup Shadow Camera
         * @zgrouppriority 4
         * @zdefault -5
         */
        this.shadowCameraBottom = new Observable(-5, v => {
            this.element.shadow.camera.bottom = v;
            this.element.shadow.camera.updateProjectionMatrix();
        });
        /**
         * Shadow camera near plane distance.
         * @zprop
         * @zgroup Shadow Camera
         * @zgrouppriority 4
         * @zdefault 0.5
         */
        this.shadowCameraNear = new Observable(0.5, v => {
            this.element.shadow.camera.near = v;
            this.element.shadow.camera.updateProjectionMatrix();
        });
        /**
         * Shadow camera far plane distance.
         * @zprop
         * @zgroup Shadow Camera
         * @zgrouppriority 4
         * @zdefault 500
         */
        this.shadowCameraFar = new Observable(500, v => {
            this.element.shadow.camera.far = v;
            this.element.shadow.camera.updateProjectionMatrix();
        });
        /**
         * Whether the light will cast shadows. Default is false.
         * @zprop
         * @zgroup Light
         * @zgrouppriority 5
         * @zdefault false
         */
        this.castShadow = new Observable(false, v => (this.element.castShadow = v), false, true);
    }
}
