import { Behavior, Observable, registerBehaviorRunAtDesignTime } from '@zcomponent/core';
/**
 * A behavior that controls the influence of a morph target.
 *
 * This behavior is registered to run at design time.
 * @zbehavior
 * @zparents three/Object3D/GLTF
 */
export class MorphTarget extends Behavior {
    /**
     * Constructs a new MorphTarget Behavior.
     * @param contextManager - The context manager.
     * @param instance - The GLTF instance.
     * @param constructorProps - The properties required to construct the MorphTarget Behavior.
     */
    constructor(contextManager, instance, constructorProps) {
        super(contextManager, instance);
        this.constructorProps = constructorProps;
        /**
         * The influence of the morph target.
         * @zprop
         * @zdefault 0
         * @ztype proportion
         */
        this.influence = new Observable(0);
        this._targets = [];
        this._update = () => {
            for (const target of this._targets) {
                const indx = target.morphTargetDictionary?.[this.constructorProps.name];
                if (indx === undefined)
                    continue;
                if (!Array.isArray(target.morphTargetInfluences))
                    continue;
                target.morphTargetInfluences[indx] = this.influence.value;
            }
        };
        this._initialize = (morphTargets) => {
            this._targets = [...(morphTargets.get(this.constructorProps.name) ?? new Set())];
            this._update();
        };
        this.register(this.influence, this._update);
        this.register(this.instance.morphTargetMeshes, this._initialize);
    }
}
registerBehaviorRunAtDesignTime(MorphTarget);
