import { Component, Observable, isDesignTime } from '@zcomponent/core';
import * as THREE from 'three';
import { Sky } from 'three/examples/jsm/objects/Sky';
import { useRenderer } from '../../context';
import { useScene } from '../../scenecontext';
/**
 * A sky environment component.
 *
 * It renders a sky environment map that can be used as the scene's environment map.
 *
 * @see https://threejs.org/docs/#api/en/scenes/Scene.environment
 * @zcomponent
 * @zgroup Environment
 * @zicon environment
 * @ztag three/Environment/SkyEnvironment
 * @zparents three/Object3D/Group/**
 */
export class SkyEnvironment extends Component {
    /**
     * Constructs a new SkyEnvironment.
     * @param contextManager - The context manager.
     * @param props - The properties required to construct a SkyEnvironment.
     */
    constructor(contextManager, props) {
        super(contextManager, props);
        this.skyScene = new THREE.Scene();
        this.element = new Sky();
        this.environmentMapSkyElement = new Sky();
        this.sun = new THREE.Vector3();
        this.uniforms = {
            turbidity: 10,
            rayleigh: 3,
            mieCoefficient: 0.005,
            mieDirectionalG: 0.7,
            elevation: 2,
            azimuth: 180,
        };
        this.useEnvironmentMap = new Observable(true, v => {
            const scene = useScene(this.contextManager);
            if (scene.environment !== this.target?.texture)
                return;
            if (v)
                scene.environment = this.target.texture;
            else
                scene.environment = null;
        });
        /**
         * Whether to use the environment map in the scene.
         * @zprop
         * @zgroup Environment Map
         * @zgrouppriority 5
         * @zdefault true
         */
        this.setSceneEnvironmentMap = new Observable(true, v => {
            this.useEnvironmentMap.value = v;
        });
        /**
         * The rayleigh of the sky.
         * @zprop
         * @zgroup Sky Appearance
         * @zgrouppriority 5
         * @ztype proportion
         * @zdefault 0.75
         */
        this.rayleigh = new Observable(0.75, v => {
            const minValue = 0.0;
            const maxValue = 4.0;
            this.uniforms.rayleigh = v * (maxValue - minValue) + minValue;
            this.updateSky();
        });
        /**
         * The mieCoefficient of the sky.
         * @zprop
         * @zgroup Sky Appearance
         * @zgrouppriority 5
         * @ztype proportion
         * @zdefault 0.05
         */
        this.mieCoefficient = new Observable(0.05, v => {
            const minValue = 0.0;
            const maxValue = 0.1;
            this.uniforms.mieCoefficient = v * (maxValue - minValue) + minValue;
            this.updateSky();
        });
        /**
         * The Sky mieDirectionalG of the sky.
         * @zprop
         * @zgroup Sky Appearance
         * @zgrouppriority 5
         * @ztype proportion
         * @zdefault 0.7
         */
        this.mieDirectionalG = new Observable(0.7, v => {
            const minValue = 0.0;
            const maxValue = 1.0;
            this.uniforms.mieDirectionalG = v * (maxValue - minValue) + minValue;
            this.updateSky();
        });
        /**
         * The elevation of the sun.
         * @zprop
         * @zgroup Sky Appearance
         * @zgrouppriority 5
         * @ztype proportion
         * @zdefault 0.022
         */
        this.elevation = new Observable(0.022, v => {
            const minValue = 0.0;
            const maxValue = 90.0;
            this.uniforms.elevation = v * (maxValue - minValue) + minValue;
            this.updateSky();
        });
        /**
         * The azimuth of the sun.
         * @zprop
         * @zgroup Sky Appearance
         * @zgrouppriority 5
         * @ztype proportion
         * @zdefault 0.5
         */
        this.azimuth = new Observable(0.5, v => {
            const minValue = -180.0;
            const maxValue = 180.0;
            this.uniforms.azimuth = v * (maxValue - minValue) + minValue;
            this.updateSky();
        });
        /**
         * Sets the visibility of the sky.
         * This does not affect the environment map.
         * @zprop
         * @zgroup Appearance
         * @zgrouppriority 5
         * @zdefault true
         */
        this.visible = new Observable(true, v => {
            this.element.visible = v;
        });
        const renderer = useRenderer(this.contextManager);
        if (!(renderer instanceof THREE.WebGLRenderer))
            return;
        this.pmrem = new THREE.PMREMGenerator(renderer);
        const showAtRuntime = props.showAtRunTime ?? false;
        if (!isDesignTime(this.contextManager) && !showAtRuntime) {
            return;
        }
        this.element.scale.setScalar(450000);
        this.environmentMapSkyElement.scale.setScalar(450000);
        this.skyScene.add(this.environmentMapSkyElement);
        this.skyScene.add(this.element);
        this.updateSky();
        const scene = useScene(this.contextManager);
        scene.add(this.element);
    }
    /**
     * The environment map.
     */
    get environmentMap() {
        return this.target?.texture;
    }
    updateSky() {
        const renderer = useRenderer(this.contextManager);
        if (!(renderer instanceof THREE.WebGLRenderer))
            return;
        const updateUniforms = (sky) => {
            const uniforms = sky.material.uniforms;
            uniforms['turbidity'].value = this.uniforms.turbidity;
            uniforms['rayleigh'].value = this.uniforms.rayleigh;
            uniforms['mieCoefficient'].value = this.uniforms.mieCoefficient;
            uniforms['mieDirectionalG'].value = this.uniforms.mieDirectionalG;
            const phi = THREE.MathUtils.degToRad(90 - this.uniforms.elevation);
            const theta = THREE.MathUtils.degToRad(this.uniforms.azimuth);
            this.sun.setFromSphericalCoords(1, phi, theta);
            uniforms['sunPosition'].value.copy(this.sun);
        };
        updateUniforms(this.environmentMapSkyElement);
        updateUniforms(this.element);
        this.target?.dispose();
        this.target = this.pmrem.fromScene(this.skyScene, 0, 1, 2000000);
        if (this.useEnvironmentMap.value) {
            const scene = useScene(this.contextManager);
            scene.environment = this.target.texture;
        }
    }
    /**
     * Disposes the SkyEnvironment.
     */
    dispose() {
        const scene = useScene(this.contextManager);
        scene.remove(this.element);
        if (scene.environment === this.target?.texture)
            scene.environment = null;
        this.pmrem.dispose();
        this.target?.dispose();
        this.environmentMapSkyElement.material.dispose();
        this.skyScene.remove(this.element);
        this.element.material.dispose();
        return super.dispose();
    }
}
