function calculateArchRadius(lineLengthX, lineLengthY) {
    const RADIUS_MULTIPLIER = 1.5;
    const midpointX = lineLengthX / 2;
    const midpointY = lineLengthY / 2;
    const diagonalLength = Math.sqrt(Math.pow(midpointX, 2) + Math.pow(midpointY, 2));
    const radius = diagonalLength / 2;
    return radius * RADIUS_MULTIPLIER;
}
