import * as THREE from 'three';
export class FocusManager {
    constructor() {
        this._raycaster = new THREE.Raycaster();
        this._tempVector = new THREE.Vector3();
        this._tempVector2 = new THREE.Vector3();
        this._tempVector3 = new THREE.Vector3();
        this._axis = new THREE.Vector3(0, 1, 0);
        this._startPosition = new THREE.Vector3();
        this._targetPosition = new THREE.Vector3();
        this._startTarget = new THREE.Vector3();
        this._endTarget = new THREE.Vector3();
        this._isAnimating = false;
        this._animationStartTime = 0;
        this._camera = null;
        this._orbit = null;
        this._box = new THREE.Box3();
        this._center = new THREE.Vector3();
    }
    update() {
        if (this._isAnimating && this._camera && this._orbit) {
            const elapsedTime = Date.now() - this._animationStartTime;
            const progress = Math.min(elapsedTime / FocusManager.ANIMATION_DURATION, 1);
            const easedProgress = this._easeInOutCubic(progress);
            this._camera.position.lerpVectors(this._startPosition, this._targetPosition, easedProgress);
            this._orbit.target.lerpVectors(this._startTarget, this._endTarget, easedProgress);
            this._orbit.update();
            if (progress >= 1)
                this._isAnimating = false;
        }
    }
    focus(selection, findObjectById, camera, orbit, scene) {
        this._box.makeEmpty();
        const ids = Object.keys(selection);
        this._center.set(0, 0, 0);
        let length = 10;
        for (const id of ids) {
            const obj = findObjectById(id);
            if (!obj)
                continue;
            this._box.expandByObject(obj);
        }
        if (this._box.isEmpty()) {
            let count = 0;
            for (const id of ids) {
                const obj = findObjectById(id);
                if (!obj)
                    continue;
                this._center.add(obj.position);
                count++;
            }
            if (count > 0)
                this._center.divideScalar(count);
        }
        else {
            this._box.getSize(this._tempVector3);
            length = this._tempVector3.length();
            this._box.getCenter(this._center);
        }
        const targetPosition = this._findSuitablePosition(this._center, length, selection, findObjectById, camera, orbit, scene);
        if (targetPosition)
            this._startAnimation(camera, orbit, targetPosition, this._center);
    }
    _findSuitablePosition(center, length, selection, findObjectById, camera, orbit, scene) {
        this._tempVector.set(length * FocusManager.VECTOR_SCALE.x, length * FocusManager.VECTOR_SCALE.y, length * FocusManager.VECTOR_SCALE.z);
        const originalPosition = camera.position.clone();
        const originalTarget = orbit.target.clone();
        for (let i = 0; i < FocusManager.FULL_ROTATION; i += FocusManager.ROTATION_STEP) {
            this._tempVector2.copy(center).add(this._tempVector);
            camera.position.copy(this._tempVector2);
            orbit.target.copy(center);
            orbit.update();
            camera.updateMatrixWorld(true);
            this._raycaster.setFromCamera(new THREE.Vector2(0, 0), camera);
            const intersections = this._raycaster.intersectObject(scene, true);
            if (intersections.length === 0) {
                this._resetCameraAndOrbit(camera, orbit, originalPosition, originalTarget);
                return this._tempVector2.clone();
            }
            if (this._allIntersectionsInSelection(intersections, selection, findObjectById)) {
                this._resetCameraAndOrbit(camera, orbit, originalPosition, originalTarget);
                return this._tempVector2.clone();
            }
            this._tempVector.applyAxisAngle(this._axis, (Math.PI * FocusManager.ROTATION_STEP) / 180);
        }
        this._resetCameraAndOrbit(camera, orbit, originalPosition, originalTarget);
        return null;
    }
    _resetCameraAndOrbit(camera, orbit, originalPosition, originalTarget) {
        camera.position.copy(originalPosition);
        orbit.target.copy(originalTarget);
        orbit.update();
    }
    _allIntersectionsInSelection(intersections, selection, findObjectById) {
        for (const intersection of intersections) {
            const id = this._findIDOfObject(intersection.object, findObjectById);
            if (id && !selection[id])
                return false;
        }
        return true;
    }
    _findIDOfObject(obj, findObjectById) {
        let current = obj;
        while (current) {
            for (const [id, foundObj] of Object.entries(findObjectById)) {
                if (foundObj === current)
                    return id;
            }
            current = current.parent;
        }
        return undefined;
    }
    _startAnimation(camera, orbit, targetPosition, targetCenter) {
        this._isAnimating = true;
        this._animationStartTime = Date.now();
        this._startPosition.copy(camera.position);
        this._targetPosition.copy(targetPosition);
        this._startTarget.copy(orbit.target);
        this._endTarget.copy(targetCenter);
        this._camera = camera;
        this._orbit = orbit;
    }
    _easeInOutCubic(t) {
        return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
    }
}
FocusManager.ANIMATION_DURATION = 500;
FocusManager.ROTATION_STEP = 30;
FocusManager.FULL_ROTATION = 360;
FocusManager.VECTOR_SCALE = {
    x: 1.1,
    y: 1,
    z: 1.3,
};
