import { Behavior, Observable, registerBehaviorRunAtDesignTime, useOnBeforeRender } from '@zcomponent/core';
import * as THREE from 'three';
/**
 * A behavior that overrides the opacity of the object.
 *
 *
 * It iterates over all the materials of the object and sets their opacity to the value of the behavior.
 *
 * This behavior is registered to run at design time.
 *
 * @see https://threejs.org/docs/?q=materia#api/en/materials/Material.opacity
 * @zbehavior
 * @zparents three/Object3D/**
 * @zgroup Appearance
 * @zicon opacity
 */
export class OverrideOpacity extends Behavior {
    /**
     * Constructs a new OverrideOpacity Behavior.
     * @param contextManager - The context manager.
     * @param instance - The Object3D instance.
     */
    constructor(contextManager, instance) {
        super(contextManager, instance);
        this.instance = instance;
        /**
         * The opacity to set on the object.
         * A value of 0.0 indicates fully transparent, 1.0 is fully opaque.
         * @zprop
         * @ztype proportion
         * @zdefault 1
         */
        this.opacity = new Observable(1);
        /**
         * Whether to set the opacity as a proportion of the original value.
         * @zprop
         * @zdefault true
         */
        this.asProportionOfOriginalValue = new Observable(true);
        this._defaultValues = new Map();
        this._update = () => {
            this.instance.element.traverse(obj => {
                if (!(obj instanceof THREE.Mesh) && !(obj instanceof THREE.SkinnedMesh))
                    return;
                if (Array.isArray(obj.material))
                    obj.material.forEach(entry => this._handleMaterial(entry));
                else
                    this._handleMaterial(obj.material);
            });
        };
        this.register(useOnBeforeRender(this.contextManager), this._update, { bindWhenDisabled: true });
    }
    _handleMaterial(m) {
        if (this.enabledResolved.value)
            this._setOnMaterial(m);
        else
            this._unsetOnMaterial(m);
    }
    _setOnMaterial(m) {
        let existing = this._defaultValues.get(m);
        if (!existing) {
            existing = { opacity: m.opacity, transparent: m.transparent };
            this._defaultValues.set(m, existing);
        }
        m.opacity = this.opacity.value * (this.asProportionOfOriginalValue.value ? existing.opacity : 1);
        const shouldBeTransparent = m.opacity === 1 ? existing.transparent : true;
        if (m.transparent !== shouldBeTransparent) {
            m.transparent = shouldBeTransparent;
            m.needsUpdate = true;
        }
    }
    _unsetOnMaterial(m) {
        const existing = this._defaultValues.get(m);
        if (!existing)
            return;
        m.opacity = existing.opacity;
        m.transparent = existing.transparent;
    }
    /**
     * Disposes the OverrideOpacity Behavior.
     */
    dispose() {
        this.instance.element.traverse(obj => {
            if (!(obj instanceof THREE.Mesh))
                return;
            if (Array.isArray(obj.material))
                obj.material.forEach(entry => this._unsetOnMaterial(entry));
            else
                this._unsetOnMaterial(obj.material);
        });
        return super.dispose();
    }
}
registerBehaviorRunAtDesignTime(OverrideOpacity);
