import { Component } from '@zcomponent/core';
import { ThreeContext } from '../../context';
/**
 * A component for adding postprocessing passes to the effect pipeline.
 */
export class Pass extends Component {
    /**
     * Constructs a pass.
     * @param contextManager - The context manager.
     * @param props - The properties for pass construction.
     * @param root - The root pass.
     */
    constructor(contextManager, props, root) {
        super(contextManager, props);
        this.root = root;
        contextManager.get(ThreeContext).effectPipeline.value.registerPass(root, props.renderPriority ?? 1);
    }
    dispose() {
        this.contextManager.get(ThreeContext).effectPipeline.value.unregisterPass(this.root);
        return super.dispose();
    }
}
