import { Event } from '../event';
import { Observable } from '../observable';
import { AnimationEvents } from './animation';
import { StreamState } from './stream';
import { resolveClipTimeLoops } from './tracks/track';
/**
 * Represents a clip within a layer of an animation.
 * Manages playback, state transitions, and property computations for the clip.
 *
 */
export class LayerClip {
    /**
     * Creates an instance of LayerClip.
     * @param layer - The layer that this clip belongs to.
     * @param clip - The clip that this layer clip is based on.
     * @param scriptName - The name of the script that created this layer clip.
     * @param id - The ID of the layer clip.
     */
    constructor(layer, clip, scriptName, id) {
        this.layer = layer;
        this.clip = clip;
        this.scriptName = scriptName;
        this.id = id;
        /**
         * Default behavior for whether the clip loops when it reaches the end.
         */
        this.defaultLoop = false;
        /**
         * Default speed at which the clip plays.
         */
        this.defaultPlaySpeed = 1;
        /**
         * Indicates if the clip should automatically start playing at the beginning of the animation.
         */
        this.playAtStart = false;
        this._t0 = 0;
        this._pauseTime = 0;
        // private _s0: number = 0;
        this._rate = 1;
        this._loop = false;
        this._stopped = false;
        this._state = StreamState.Paused;
        this.state = new Observable(this._state);
        this.playing = new Observable(false);
        this.stalled = new Observable(false);
        this.active = new Observable(false);
        this.onPlaying = new Event();
        this.onPaused = new Event();
        this.onEnded = new Event();
        this.onLoop = new Event();
        this._clipDirty = (v) => {
            if (v)
                this._lastClipTime = undefined;
        };
        this._stateUpdate = (s) => {
            this.playing.value = s === StreamState.Playing;
            switch (s) {
                case StreamState.Ended:
                    this.onEnded.emit(this);
                    break;
                case StreamState.Playing:
                    this.onPlaying.emit(this);
                    break;
                case StreamState.Paused:
                    this.onPaused.emit(this);
                    break;
            }
        };
        this.animation = layer.animation;
        this._t1 = clip.length;
        layer._registerLayerClip(this);
        this.clip.influencedPathsDirty.addListener(this._clipDirty);
        if (id)
            layer.animation.layerClipByID.set(id, this);
        this.state.addListener(this._stateUpdate);
    }
    /** @internal */
    tick(touchedPaths, force) {
        const t = this._getTime();
        if (this._stallStartTime !== undefined) {
            if (!this.clip.isStalled())
                this._cancelStall();
        }
        else if (this._state === StreamState.Playing) {
            if (this.clip.isStalled()) {
                this._stallStartTime = t;
                this.stalled.value = true;
            }
        }
        const t0 = this._t0 + (t - (this._pauseTime ?? t)) + (t - (this._stallStartTime ?? t));
        const t1 = this._t1 + (t - (this._pauseTime ?? t)) + (t - (this._stallStartTime ?? t));
        const ct = this.clip.resolveClipTime(t, t0, this._rate >= 0 ? 0 : this.clip.length, this._rate, t1);
        this._lastTickTime = ct;
        if (ct !== this._lastClipTime || force) {
            touchedPaths.push(...this.clip.influencedPaths);
        }
        if (this._state === StreamState.Playing && t >= this._t1) {
            this.pause();
            this._state = StreamState.Ended;
            this.state.value = this._state;
        }
        else {
            const [bt, loop] = resolveClipTimeLoops(t, t0, this._rate >= 0 ? 0 : this.clip.length, this._rate, this.clip.length, this._rate < 0, t1);
            this.clip.streamTick(this._state, bt, this._rate, this.layer.active === this, this.layer.active, loop !== this._lastLoop, this._stallStartTime !== undefined, 1);
            const isNewLoop = this._lastLoop !== undefined && this._lastLoop !== loop;
            this._lastLoop = loop;
            if (isNewLoop)
                this.onLoop.emit(this);
        }
    }
    /**
     * Computes the property value for a specific path based on the current state of the clip.
     *
     * @param p The path of the property to compute.
     * @param valueBefore The initial value before applying clip-specific computations.
     * @returns The computed property value.
     */
    computePathProperty(p, valueBefore) {
        const t = this._getTime();
        const t0 = this._t0 + (t - (this._pauseTime ?? t)) + (t - (this._stallStartTime ?? t));
        const t1 = this._t1 + (t - (this._pauseTime ?? t)) + (t - (this._stallStartTime ?? t));
        const ct = this.clip.resolveClipTime(t, t0, this._rate >= 0 ? 0 : this.clip.length, this._rate, t1);
        this._lastClipTime = ct;
        return this.clip.computePathProperty(ct ?? 0, p, valueBefore);
    }
    /**
     * Estimates the remaining time for the clip to finish playing.
     *
     * @returns The estimated remaining time in milliseconds.
     */
    getRemainingTimeEstimate() {
        const t = this._getTime();
        const t1 = this._t1 + (t - (this._pauseTime ?? t)) + (t - (this._stallStartTime ?? t));
        return t1 - t;
    }
    _getTime() {
        return Math.floor(this.timeSource?.() ?? this.animation.timeSource?.() ?? performance.now());
    }
    /**
     * Queues the LayerClip for playback with optional play options.
     *
     * @param opts Optional play options to customize playback behavior.
     */
    queue(opts) {
        this.layer.queue(this, opts);
        return this;
    }
    /**
     * @returns The length of the clip.
     */
    length() {
        return this.clip.length;
    }
    /**
     * Plays the clip, optionally with specified play options.
     *
     * @param opts Optional play options to customize playback behavior.
     */
    play(opts) {
        if (opts?.speed === 0) {
            return this.pause();
        }
        this._stopped = false;
        this._loop = opts?.loop ?? this.defaultLoop;
        const t = this._getTime();
        if (this._state === StreamState.Ended) {
            this._t0 = t;
        }
        else if (this._pauseTime !== undefined) {
            this._t0 = t - (this._pauseTime - this._t0);
        }
        if (Math.sign(this._rate) !== Math.sign(opts?.speed ?? 1)) {
            this._t0 = 2 * t - this.clip.length - this._t0;
        }
        delete this._pauseTime;
        this._rate = opts?.speed ?? this.defaultPlaySpeed;
        if (this._loop)
            this._t1 = Infinity;
        else {
            if (this._rate < 0)
                this._t1 = this._t0 + this.clip.length / -this._rate;
            else if (this._rate > 0)
                this._t1 = this._t0 + this.clip.length / this._rate;
            else
                this._t1 = Infinity;
        }
        const t0 = this._t0 + (t - (this._pauseTime ?? t));
        const t1 = this._t1 + (t - (this._pauseTime ?? t));
        this._state = StreamState.Playing;
        this.animation._pendingEvents.push({ evt: AnimationEvents.onLayerClipState, args: [this] });
        this._lastClipTime = undefined;
        this._lastTickTime = undefined;
        if (this.layer.active !== this) {
            this.layer._activateLayerClip(this, opts);
            this.layer._evaulate();
        }
        if (this.clip.isStalled()) {
            this._stallStartTime = t;
            this.stalled.value = true;
        }
        const [bt, loop] = resolveClipTimeLoops(t, t0, this._rate >= 0 ? 0 : this.clip.length, this._rate, this.clip.length, this._rate < 0, t1);
        this.clip.streamTick(this._state, bt, this._rate, this.layer.active === this, this.layer.active, loop !== this._lastLoop, this._stallStartTime !== undefined, 1);
        this._lastLoop = loop;
        this.state.value = this._state;
        return this;
    }
    /**
     * Pauses the playback of the clip.
     */
    pause() {
        delete this._lastLoop;
        if (this._pauseTime !== undefined || this._state !== StreamState.Playing)
            return this;
        this._state = StreamState.Paused;
        this.animation._pendingEvents.push({ evt: AnimationEvents.onLayerClipState, args: [this] });
        this._pauseTime = this._getTime();
        this._cancelStall();
        this.clip.streamPause(this.layer.active === this, this.layer.active);
        this.state.value = this._state;
        return this;
    }
    _cancelStall() {
        if (this._stallStartTime === undefined)
            return;
        const t = this._getTime();
        this._t0 += t - this._stallStartTime;
        this._t1 += t - this._stallStartTime;
        delete this._stallStartTime;
        this.stalled.value = false;
    }
    /**
     * Seeks to a specific time within the clip and optionally applies fade parameters.
     *
     * @param ct The clip time to seek to.
     * @param opts Optional seek options, including fade parameters.
     */
    seek(ct, opts) {
        const clampedTime = Math.max(0, Math.min(ct, this.clip.length));
        const t = this._getTime();
        this._stopped = false;
        if (this._rate >= 0) {
            this._t0 = t - clampedTime / this._rate;
            this._t1 = this._t0 + this.clip.length / this._rate;
        }
        else {
            this._t0 = t - (this.clip.length - clampedTime) / -this._rate;
            this._t1 = this._t0 + this.clip.length / -this._rate;
        }
        if (this._pauseTime !== undefined) {
            this._pauseTime = t;
        }
        if (this._loop)
            this._t1 = Infinity;
        this._lastTickTime = clampedTime;
        this._lastClipTime = clampedTime;
        if (this.layer.active !== this && !opts?.dontActivateLayer) {
            this.layer._activateLayerClip(this, { fade: opts?.fade });
        }
        delete this._lastLoop;
        delete this._stallStartTime;
        this.clip.streamSeek(clampedTime, this._rate, this.layer.active === this, this.layer.active);
        this.layer._evaulate();
        return this;
    }
    /** @internal */
    _serialize(state) {
        if (this.id === undefined)
            return;
        const timeOfSerialization = this._getTime();
        const t0 = this._t0 - timeOfSerialization;
        const pauseTime = this._pauseTime === undefined ? undefined : this._pauseTime - timeOfSerialization;
        const t1 = isFinite(this._t1) ? this._t1 - timeOfSerialization : null;
        const ret = {
            t0,
            t1,
            pauseTime,
            rate: this._rate,
            loop: this._loop,
            stopped: this._stopped,
            state: this._state,
        };
        state.byLayerClip[this.id] = ret;
    }
    /** @internal */
    _restore(state) {
        if (this.id === undefined)
            return;
        const entry = state.byLayerClip[this.id];
        if (!entry)
            return;
        const timeOfDeserialization = this._getTime();
        this._t0 = timeOfDeserialization + entry.t0;
        this._t1 = entry.t1 === null ? Infinity : timeOfDeserialization + entry.t1;
        this._pauseTime = entry.pauseTime === undefined ? undefined : timeOfDeserialization + entry.pauseTime;
        this._rate = entry.rate;
        this._loop = entry.loop;
        this._stopped = entry.stopped;
        this._state = entry.state;
        this.state.value = this._state;
    }
    /**
     * Gets the current clip time.
     *
     * @returns The current time within the clip.
     */
    get clipTime() {
        return this._lastTickTime !== undefined ? this._lastTickTime : this.defaultPlaySpeed > 0 ? 0 : this.clip.length;
    }
    /**
     * Stops the clip's playback.
     */
    stop() {
        this._stopped = true;
        this._pauseTime = this._t0;
        this._lastClipTime = undefined;
        this._lastTickTime = undefined;
        delete this._lastLoop;
        delete this._stallStartTime;
        this._rate = 1;
        this.clip.streamTick(StreamState.Ended, this._t0, 1, this.layer.active === this, this.layer.active, true);
        this._state = StreamState.Ended;
        this.animation._pendingEvents.push({ evt: AnimationEvents.onLayerClipState, args: [this] });
        this.state.value = this._state;
        return this;
    }
    /**
     * Determines if the clip is currently stalled.
     *
     * @returns True if the clip is stalled, false otherwise.
     */
    isStalled() {
        return this._stallStartTime !== undefined;
    }
}
