/**
 * The base class for classes that hold a set of functions to be called in response
 * to an event or change in value, e.g. Observable and Event.
 */
export class Emitter {
    constructor() {
        this._funcs = [];
        this._emitting = false;
        this._toUnbind = new Set();
        this._needsSort = false;
    }
    /**
     * Clears all listeners from the event.
     */
    clearListeners() {
        this._funcs = [];
        this._needsSort = false;
    }
    /**
     * Add a new handler function
     * @param f - The callback function to be bound.
     */
    addListener(f, priority = 0) {
        this._funcs.push([f, priority]);
        this._needsSort = true;
    }
    /**
     * Unbind an existing function
     * @param f - The callback function to be unbound.
     */
    removeListener(f) {
        if (this._emitting) {
            this._toUnbind.add(f);
            return;
        }
        this._toUnbind.delete(f);
        const indx = this._funcs.findIndex(entry => entry[0] === f);
        if (indx > -1) {
            this._funcs.splice(indx, 1);
        }
    }
    /**
     * Returns a promise that will be resolved the next time this object emits.
     */
    get next() {
        if (!this._next) {
            this._next = new Promise(resolve => {
                this._nextFn = resolve;
            });
        }
        return this._next;
    }
    /**
     * Emit an event
     *
     * @param a - The argument to pass to handler functions.
     */
    _emit(...args) {
        if (this._needsSort) {
            this._funcs.sort((a, b) => b[1] - a[1]);
            this._needsSort = false;
        }
        this._emitting = true;
        for (let i = 0, total = this._funcs.length; i < total; i++) {
            const fn = this._funcs[i][0];
            try {
                if (this._toUnbind.has(fn))
                    continue;
                fn(...args);
            }
            catch (ex) {
                console.log('Exception in event handler', ex);
            }
        }
        this._emitting = false;
        if (this._toUnbind.size > 0) {
            this._toUnbind.forEach(fn => this.removeListener(fn));
        }
        if (this._nextFn) {
            const fn = this._nextFn;
            delete this._next;
            delete this._nextFn;
            try {
                fn(args);
            }
            catch (ex) {
                console.log('Exception in event handler', ex);
            }
        }
    }
}
