import { Component, constructed, Observable } from '@zcomponent/core';
import * as THREE from 'three';
import { Object3D } from '../Object3D';
const nullGeometry = new THREE.BufferGeometry();
const nullMaterial = new THREE.MeshBasicMaterial();
/**
 * The base class for mesh components.
 *
 * Root element: [THREE.Mesh](https://threejs.org/docs/index.html#api/en/objects/Mesh)
 * @zcomponent
 * @zgroup Meshes
 * @zicon deployed_code
 * @ztag three/Object3D/Mesh/Mesh
 * @zparents three/Object3D/Group/**
 */
export class Mesh extends Object3D {
    constructor(contextManager, constructorProps) {
        const obj = constructorProps.mesh ?? new THREE.Mesh(constructorProps.geometry ?? nullGeometry, constructorProps.material ?? nullMaterial.clone());
        super(contextManager, constructorProps, obj);
        this.constructorProps = constructorProps;
        this._resolveMaterials = () => {
            if (this.material?.value) {
                const zcomp = this.getZComponentInstance();
                const materials = [];
                if (zcomp) {
                    for (const entry of this.material.value) {
                        const material = zcomp.entityByID.get(entry);
                        if (material && material instanceof Component) {
                            for (const element of material.elementsResolved) {
                                if (element instanceof THREE.Material)
                                    materials.push(element);
                            }
                        }
                    }
                }
                if (materials.length === 1)
                    this.element.material = materials[0];
                else
                    this.element.material = materials;
                return;
            }
            let foundMaterial = false;
            for (const child of this.children) {
                for (const element of child.elementsResolved) {
                    if (element instanceof THREE.Material) {
                        this.element.material = element;
                        foundMaterial = true;
                    }
                }
            }
            if (!foundMaterial) {
                this.element.material = this.constructorProps?.material ?? nullMaterial.clone();
            }
        };
        /**
         * The material(s) to use for rendering.
         * @zprop
         * @zvalues nodeids three/Material/Mesh/**
         * @zgroup Appearance
         * @zgrouppriority 11
         */
        this.material = new Observable(undefined, this._resolveMaterials);
        for (const child of this.children) {
            for (const element of child.elementsResolved) {
                if (element instanceof THREE.BufferGeometry)
                    this.element.geometry = element;
            }
        }
        this.element.updateMorphTargets();
        constructed(contextManager).then(this._resolveMaterials);
    }
}
