import { Context, Observable } from '@zcomponent/core';
export class EditorContext extends Context {
    constructor(ontextManager, constructorProps) {
        super(ontextManager, constructorProps);
        this.toolbar = new Observable(undefined, undefined, false);
        this.transformControls = new Observable(undefined, undefined, false);
        this.orbitControls = new Observable(undefined, undefined, false);
        this.helpersGroup = new Observable(undefined, undefined, false);
        /**
         * Controls whether the transform controls and transform properties are disabled.
         *
         * When true, the following will be disabled:
         * - Transform controls visability
         * - Transform controls 'enabled' property
         * - Selection of objects in the editor
         * - Transform properties (position, rotation, scale) will be discarded
         */
        this.selectionAndTransformPropsDisabled = new Observable(false, undefined, false);
        this.dispose = () => {
            this.selectionAndTransformPropsDisabled.value = false;
            return super.dispose();
        };
    }
}
/**
 * A toolbar for the editor. Displays buttons for common actions.
 * Can be used to add custom buttons.
 */
export class EditorToolbar {
    constructor(dom) {
        this.dom = dom;
    }
    /**
     * @param element An element to add to the toolbar.
     */
    addElement(element, order) {
        element.style.order = order.toString();
        this.dom.append(element);
    }
    /**
     * @param element An element to remove from the toolbar.
     */
    removeElement(element) {
        this.dom.removeChild(element);
    }
}
export function createIconRadio(icon, name) {
    const label = document.createElement('label');
    const input = document.createElement('input');
    input.type = 'radio';
    label.append(input);
    label.append(constructElement(icon) ?? '');
    label.setAttribute('name', name);
    input.setAttribute('name', name);
    return [label, input];
}
function constructElement(html) {
    const template = document.createElement('template');
    template.innerHTML = html;
    return template.content.firstChild;
}
/**
 * Gets the editors transform controls.
 */
export function useTransformControls(contextManager) {
    return contextManager.get(EditorContext).transformControls;
}
/**
 * Gets the editors orbit controls.
 */
export function useOrbitControls(contextManager) {
    return contextManager.get(EditorContext).orbitControls;
}
/**
 * Gets the editors toolbar.
 */
export function useToolbar(contextManager) {
    return contextManager.get(EditorContext).toolbar;
}
