import { Behavior, Observable, registerBehaviorRunAtDesignTime, useOnBeforeRender } from '@zcomponent/core';
import { useScene } from '../scenecontext';
import * as THREE from 'three';
import { OnBeforeRenderPriority } from '../priorities';
/**
 * Renders a bounding box around the object.
 * This is useful for debugging purposes.
 *
 * This behavior is registered to run at design time.
 * @zbehavior
 * @zparents three/Object3D/**
 * @zgroup Helpers
 * @zicon view_in_ar
 */
export class BoundingBox extends Behavior {
    /**
     * Constructs a new BoundingBox Behavior.
     * @param contextManager - The context manager.
     * @param instance - The Object3D instance.
     */
    constructor(contextManager, instance) {
        super(contextManager, instance);
        /**
         * The color of the bounding box.
         * @zprop
         * @zgroup BoxHelper
         * @zgrouppriority 20
         * @ztype color-norm-rgb-linear
         * @zdefault [0, 0, 1]
         */
        this.color = new Observable([0, 0, 1]);
        this._frame = () => {
            this.instance.element.updateWorldMatrix(true, true);
            try {
                this._boxHelper.update();
                this._boxHelper.visible = true;
            }
            catch {
                this._boxHelper.visible = false;
            }
        };
        this.register(useOnBeforeRender(contextManager), this._frame, OnBeforeRenderPriority.Helpers);
        const scene = useScene(contextManager);
        this._boxHelper = new THREE.BoxHelper(instance.element);
        scene.add(this._boxHelper);
        const material = this._boxHelper.material;
        if (material instanceof THREE.LineBasicMaterial) {
            this.register(this.color, v => material.color.setRGB(...v));
        }
        this.register(this.enabledResolved, v => {
            this._boxHelper.visible = v;
        }, { bindWhenDisabled: true });
    }
    /**
     * Disposes the BoundingBox Behavior.
     */
    dispose() {
        this._boxHelper.dispose();
        this._boxHelper.removeFromParent();
        return super.dispose();
    }
}
registerBehaviorRunAtDesignTime(BoundingBox);
