import { Observable } from '@zcomponent/core';
import * as THREE from 'three';
import { Material } from './Material';
/**
 * This material can receive shadows, but otherwise is completely transparent.
 *
 * Root element: [THREE.ShadowMaterial](https://threejs.org/docs/index.html#api/en/materials/ShadowMaterial)
 * @zcomponent
 * @zgroup Materials
 * @zicon material
 * @ztag three/Material/Mesh/MeshShadowMaterial
 * @zparents three/Object3D/Mesh/**
 * @zparents three/Object3D/GLTF
 * @zparents three/Object3D/Group/**
 */
export class MeshShadowMaterial extends Material {
    /**
     * Constructs a new shadow material.
     * @param contextManager - Context manager.
     * @param props - Properties.
     */
    constructor(contextManager, props) {
        super(contextManager, props, new THREE.ShadowMaterial());
        /**
         * Color of the material, by default set to black.
         * @zprop
         * @zgroup MeshShadowMaterial
         * @zgrouppriority 20
         * @ztype color-norm-rgb-linear
         * @zdefault [0, 0, 0]
         */
        this.color = new Observable([0, 0, 0], v => this.element.color.setRGB(...v));
        /**
         * Weather the material is affected by fog.
         * @zprop
         * @zgroup MeshShadowMaterial
         * @zgrouppriority 20
         * @zdefault true
         */
        this.fog = new Observable(true, v => (this.element.fog = v));
        /**
         * Defines whether this material is transparent.
         * @zprop
         * @zgroup Material
         * @zgrouppriority 10
         * @zdefault true
         */
        this.transparent = new Observable(true, v => (this.element.transparent = v));
    }
}
