import { TriggerShape } from './ITrigger';
import { OBBTrigger } from './OBBTrigger';
/**
 * A cube trigger component.
 * @zcomponent
 * @zgroup Trigger
 * @zicon shapes
 * @zparents three/Object3D/**
 */
export class CubeTrigger extends OBBTrigger {
    /**
     * Constructs a cube trigger.
     * @param ctx - The context manager.
     * @param props - The properties for trigger construction, including shape.
     */
    constructor(ctx, props) {
        super(ctx, { ...props, shape: TriggerShape.Cube });
    }
}
