import { constructed, Event, isDesignTime, Observable, useOnBeforeRender } from '@zcomponent/core';
import { Group } from '../Group';
import * as THREE from 'three';
import { OnBeforeRenderPriority } from '../../priorities';
import { useRenderer } from '../../context';
import { WebXRContext } from '../../webxrcontext';
const _ray = new THREE.Ray();
const _matrix = new THREE.Matrix4();
const _groundPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0));
/**
 * The position of content placed in this group can be chosen by the user at the start of a WebXR session. It's particularly useful for "immersive-ar" mode.
 *
 * Root element: [THREE.Group](https://threejs.org/docs/index.html#api/en/objects/Group)
 *
 * @zcomponent
 * @zicon open_with
 * @zgroup Deprecated
 * @ztag three/Object3D/Group/WebXRPlacementGroup
 * @zparents three/Object3D/Group/**
 */
export class WebXRPlacementGroup extends Group {
    constructor(contextManager, constructorProps) {
        const innerGroup = new THREE.Group();
        super(contextManager, constructorProps, innerGroup);
        /**
         * @zui
         */
        this.onVisible = new Event();
        /** @zui */
        this.onPlaced = new Event();
        /**
         * @zui
         * @zgroup WebXRPlacementGroup
         * @zgrouppriority 20
         * @zdefault true
         */
        this.useControllerIfPresent = new Observable(true);
        /**
         * @zui
         * @zgroup WebXRPlacementGroup
         * @zgrouppriority 20
         * @zdefault "right"
         */
        this.controllerPreference = new Observable('right');
        /**
         * @zui
         * @zgroup WebXRPlacementGroup
         * @zgrouppriority 20
         * @zdefault false
         */
        this.forceGroundPlane = new Observable(false);
        /**
         * @zui
         * @zgroup Animation
         * @zgrouppriority 10
         * @zdefault false
         * @zvalues layerclipids
         */
        this.placingLayerClip = new Observable(undefined);
        /**
         * @zui
         * @zgroup Animation
         * @zgrouppriority 10
         * @zdefault false
         * @zvalues layerclipids
         */
        this.notPlacingLayerClip = new Observable(undefined);
        this._useGroundPlaneIntersection = false;
        this._isPlacing = true;
        this._updateHitSource = async () => {
            this._useGroundPlaneIntersection = true;
            this._hitSource?.cancel();
            this._hitSource = undefined;
            this._sourceSpace = undefined;
            const context = this.contextManager.get(WebXRContext);
            const session = context.currentSession.value;
            const renderer = useRenderer(this.contextManager);
            if (!(renderer instanceof THREE.WebGLRenderer) || !session)
                return;
            let space;
            if (this.useControllerIfPresent.value && context.inputSources.value.length > 0) {
                let chosenSource;
                for (const inputSource of context.inputSources.value) {
                    if (inputSource.targetRayMode === 'screen')
                        continue;
                    if (this.controllerPreference.value === 'none' || inputSource.handedness === this.controllerPreference.value) {
                        chosenSource = inputSource;
                        break;
                    }
                }
                chosenSource = chosenSource ?? context.inputSources.value[0];
                if (chosenSource?.targetRayMode === 'screen')
                    chosenSource = undefined;
                if (chosenSource)
                    space = chosenSource.targetRaySpace;
            }
            if (!space)
                space = await session.requestReferenceSpace('viewer');
            if (!space)
                return;
            try {
                this._sourceSpace = space;
                const source = await session.requestHitTestSource?.({ space });
                this._hitSource = source;
                this._useGroundPlaneIntersection = false;
            }
            catch (err) {
                console.log('Unable to get hit test source', err.toString());
            }
        };
        this._select = (evt) => {
            if (!this._isPlacing)
                return;
            if (evt.inputSource.handedness !== 'none' && this.controllerPreference.value !== 'none' && evt.inputSource.handedness !== this.controllerPreference.value)
                return;
            this._isPlacing = false;
            this.onPlaced.emit();
            if (!this.notPlacingLayerClip.value)
                return;
            const zcomponent = this.getZComponentInstance();
            const layerclip = zcomponent.animation.layerClipByID.get(this.notPlacingLayerClip.value);
            if (!layerclip)
                return;
            layerclip.play();
        };
        this._frame = () => {
            if (!this._isPlacing)
                return;
            if (this._useGroundPlaneIntersection || this.forceGroundPlane.value)
                return this._groundPlaneIntersection();
            const renderer = useRenderer(this.contextManager);
            if (!(renderer instanceof THREE.WebGLRenderer))
                return;
            if (!renderer.xr.isPresenting || !this._hitSource)
                return;
            const frame = renderer.xr.getFrame();
            if (!frame)
                return;
            const referenceSpace = renderer.xr.getReferenceSpace();
            if (!referenceSpace)
                return;
            const results = frame.getHitTestResults(this._hitSource);
            if (results.length === 0)
                return;
            if (this._innerGroup.visible === false) {
                this._innerGroup.visible = true;
                this.onVisible.emit();
            }
            const result = results[0];
            const pose = result.getPose(referenceSpace);
            if (!pose)
                return;
            this._innerGroup.matrix.fromArray(pose.transform.matrix);
            this._innerGroup.matrixWorldNeedsUpdate = true;
            this._innerGroup.updateMatrixWorld();
        };
        this.element.add(innerGroup);
        this._innerGroup = innerGroup;
        if (!isDesignTime(contextManager)) {
            this._innerGroup.visible = false;
            innerGroup.matrixAutoUpdate = false;
            const context = contextManager.get(WebXRContext);
            this.register(useOnBeforeRender(this.contextManager), this._frame, OnBeforeRenderPriority.Transforms);
            this.register(context.currentSession, this._updateHitSource);
            this.register(context.inputSources, this._updateHitSource);
            this.register(context.onSelect, this._select);
            constructed(this.contextManager).then(() => {
                if (!this.placingLayerClip.value)
                    return;
                const zcomponent = this.getZComponentInstance();
                const layerclip = zcomponent.animation.layerClipByID.get(this.placingLayerClip.value);
                if (!layerclip)
                    return;
                layerclip.play({ fade: { time: 0 } });
            });
        }
    }
    _groundPlaneIntersection() {
        const renderer = useRenderer(this.contextManager);
        if (!(renderer instanceof THREE.WebGLRenderer))
            return;
        if (!renderer.xr.isPresenting || !this._sourceSpace)
            return;
        const frame = renderer.xr.getFrame();
        if (!frame)
            return;
        const referenceSpace = renderer.xr.getReferenceSpace();
        if (!referenceSpace)
            return;
        const sourcePosition = frame.getPose(this._sourceSpace, referenceSpace);
        if (!sourcePosition)
            return;
        _ray.origin.set(0, 0, 0);
        _ray.direction.set(0, 0, -1);
        _matrix.fromArray(sourcePosition.transform.matrix);
        _ray.applyMatrix4(_matrix);
        if (!_ray.intersectPlane(_groundPlane, this._innerGroup.position))
            return;
        if (this._innerGroup.visible === false) {
            this._innerGroup.visible = true;
            this.onVisible.emit();
        }
        this._innerGroup.rotation.set(0, 0, 0);
        this._innerGroup.updateMatrix();
        this._innerGroup.matrixWorldNeedsUpdate = true;
        this._innerGroup.updateMatrixWorld();
    }
}
